def puru_markup(pose='guide', class_name='', decorative=True):
    pose = pose if pose in PURU_POSES else 'guide'
    attributes = 'aria-hidden="true"' if decorative else 'role="img" aria-label="'+_loading_escape(PURU_POSES[pose]['label'], quote=True)+'"'
    classes = _loading_escape('keco-puru keco-puru--'+pose+' '+str(class_name), quote=True)
    return '<span class="'+classes+'" '+attributes+'></span>'


def puru_intro(title, description, pose='guide', class_name=''):
    copy = '<div class="keco-puru-copy"><h2>'+_loading_escape(str(title))+'</h2><p>'+_loading_escape(str(description)).replace('\n', '<br>')+'</p></div>'
    return '<div class="keco-puru-intro '+_loading_escape(class_name, quote=True)+'">'+copy+puru_markup(pose, 'keco-puru-intro-art')+'</div>'


def puru_empty(message):
    return '<div class="ra-table-empty keco-puru-empty">'+puru_markup('inspect')+'<span>'+_loading_escape(str(message))+'</span></div>'


def puru_sprite_rule(selector, pose):
    x, y, width, height = PURU_POSES[pose]['box']
    return (selector+'{height:calc(var(--puru-size,64px)*'+str(height/width)+');'
            'background-size:'+str(1536/width*100)+'% auto;'
            'background-position:'+str(x/(1536-width)*100)+'% '+str(y/(1024-height)*100)+'%;'
            'clip-path:'+PURU_POSES[pose]['clip']+';}')


