# 휴대폰 기본 후면 카메라 호출용 고화질 촬영 컴포넌트
# ============================================================

_NATIVE_CAMERA_HTML = r"""<!doctype html>
<html lang="ko">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1">
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; padding: 2px; font-family: Arial, sans-serif; background: transparent; }
    .camera-button {
      display: flex; align-items: center; justify-content: center; gap: 8px;
      width: 100%; min-height: 52px; padding: 12px 16px;
      border: 0; border-radius: 11px; cursor: pointer;
      background: linear-gradient(135deg, #007A33, #059669);
      color: #fff; font-weight: 800; font-size: 16px;
      box-shadow: 0 3px 9px rgba(0, 122, 51, .22);
    }
    input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
    .status { margin: 9px 2px 0; color: #475569; font-size: 13px; line-height: 1.45; }
    .preview { display: none; width: 100%; max-height: 420px; object-fit: contain;
      margin-top: 10px; border-radius: 10px; background: #eef2f4; }
  </style>
</head>
<body>
  <label class="camera-button" for="cameraFile">📷 지금 사진 촬영</label>
  <input id="cameraFile" type="file" accept="image/*" capture="environment">
  <div id="status" class="status">휴대폰 기본 후면카메라로 촬영합니다.</div>
  <img id="preview" class="preview" alt="촬영 사진 미리보기">
  <script>
    const send = (type, payload = {}) => window.parent.postMessage(
      Object.assign({isStreamlitMessage: true, type: type}, payload), "*"
    );
    const resize = () => send("streamlit:setFrameHeight", {
      height: Math.max(document.documentElement.scrollHeight, document.body.scrollHeight)
    });
    const input = document.getElementById("cameraFile");
    const status = document.getElementById("status");
    const preview = document.getElementById("preview");
    input.addEventListener("change", () => {
      const file = input.files && input.files[0];
      if (!file) return;
      status.textContent = "촬영 사진을 불러오는 중입니다...";
      const reader = new FileReader();
      reader.onload = () => {
        preview.src = reader.result;
        preview.style.display = "block";
        status.textContent = "촬영 사진이 등록되었습니다.";
        send("streamlit:setComponentValue", {value: {
          data_url: reader.result,
          name: file.name || "mobile_camera.jpg",
          mime_type: file.type || "image/jpeg"
        }});
        setTimeout(resize, 100);
      };
      reader.onerror = () => { status.textContent = "사진을 불러오지 못했습니다. 다시 촬영해 주세요."; };
      reader.readAsDataURL(file);
    });
    window.addEventListener("load", () => {
      send("streamlit:componentReady", {apiVersion: 1});
      setTimeout(resize, 50);
    });
    window.addEventListener("message", event => {
      if (event.data && event.data.type === "streamlit:render") {
        setTimeout(resize, 20);
      }
    });
  </script>
</body>
</html>"""

_native_camera_dir = Path(__file__).resolve().parent / "native_camera_component"
_native_camera_dir.mkdir(parents=True, exist_ok=True)
_native_camera_index = _native_camera_dir / "index.html"
if not _native_camera_index.exists() or _native_camera_index.read_text(encoding="utf-8") != _NATIVE_CAMERA_HTML:
    _native_camera_index.write_text(_NATIVE_CAMERA_HTML, encoding="utf-8")

_native_camera_component = components.declare_component(
    "keco_native_camera",
    path=str(_native_camera_dir)
)


def native_high_quality_camera(label, key):
    """휴대폰 기본 카메라 촬영 결과를 UploadedFile과 유사한 BytesIO로 반환."""
    result = _native_camera_component(label=label, key=key, default=None)
    if not result or not result.get("data_url"):
        return None
    try:
        _, encoded = result["data_url"].split(",", 1)
        image_file = io.BytesIO(base64.b64decode(encoded))
        image_file.name = result.get("name") or "mobile_camera.jpg"
        image_file.type = result.get("mime_type") or "image/jpeg"
        image_file.seek(0)
        return image_file
    except Exception as exc:
        st.error(f"고화질 촬영 사진을 불러오지 못했습니다: {exc}")
        return None

# ============================================================
# 1. 기본 텍스트 정리
# ============================================================

def _clean_text(text):
    """Gemini Markdown 흔적 및 불필요한 문자를 정리"""
    if not text:
        return ""

    text = text.replace("**", "")
    text = text.replace("__", "")
    text = text.replace("###", "")
    text = text.replace("##", "")
    text = text.replace("#", "")
    text = text.replace("---", "")

    return text.strip()


# ============================================================
# 2. Gemini 응답을 6개 섹션으로 분리
# ============================================================

def _parse_report_sections(content):

    sections = {
        "overview": [],
        "risks": [],
        "laws": [],
        "actions": [],
        "cautions": [],
        "opinion": []
    }

    if not content:
        return sections

    # 줄 단위 정리
    lines = [
        line.strip()
        for line in content.splitlines()
        if line.strip()
    ]

    current = None

    for line in lines:

        clean = _clean_text(line)

        # -----------------------------------------
        # 섹션 제목 판별
        # -----------------------------------------

        if re.match(r"^1\.\s*점검\s*개요", clean):
            current = "overview"
            continue

        elif re.match(r"^2\.\s*주요\s*위험요인", clean):
            current = "risks"
            continue

        elif re.match(r"^3\.\s*관련\s*법령\s*및\s*기준", clean):
            current = "laws"
            continue

        elif re.match(r"^4\.\s*권장\s*조치사항", clean):
            current = "actions"
            continue

        elif re.match(r"^5\.\s*현장\s*적용\s*시\s*유의사항", clean):
            current = "cautions"
            continue

        elif re.match(r"^6\.\s*종합\s*의견", clean):
            current = "opinion"
            continue

        # -----------------------------------------
        # 구분선 제거
        # -----------------------------------------

        if set(clean.replace(" ", "")) <= {"=", "-"}:
            continue

        # -----------------------------------------
        # 현재 섹션에 추가
        # -----------------------------------------

        if current:
            sections[current].append(clean)

    return sections


# ============================================================
# 3. 위험요인 파싱
# ============================================================

def _parse_risks(lines):

    risks = []

    for line in lines:

        if line in ["해당 없음", "해당없음"]:
            continue

        # ① 위험요인 | 위험등급: 상 | 위험내용
        parts = [p.strip() for p in line.split("|")]

        if len(parts) >= 2:

            number = ""
            risk_name = ""
            grade = ""
            description = ""

            # 번호 제거
            first = parts[0]

            first = re.sub(
                r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
                "",
                first
            )

            first = re.sub(
                r"^\d+[\.\)]\s*",
                "",
                first
            )

            risk_name = first.strip()

            # 위험등급 찾기
            grade_match = re.search(
                r"위험등급\s*[:：]?\s*(상|중|하)",
                line
            )

            if grade_match:
                grade = grade_match.group(1)

            # 위험내용
            if len(parts) >= 3:
                description = parts[-1].strip()

            risks.append({
                "number": len(risks) + 1,
                "name": risk_name,
                "grade": grade if grade else "확인 필요",
                "description": description
            })

        else:

            # 파싱되지 않은 경우에도 내용을 보존
            text = re.sub(
                r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
                "",
                line
            )

            risks.append({
                "number": len(risks) + 1,
                "name": text,
                "grade": "확인 필요",
                "description": ""
            })

    return risks


# ============================================================
# 4. 법령 파싱
# ============================================================

def _parse_laws(lines):

    laws = []

    for line in lines:

        if not line:
            continue

        if line in ["해당 없음", "해당없음"]:
            continue

        text = re.sub(
            r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
            "",
            line
        )

        text = re.sub(
            r"^\d+[\.\)]\s*",
            "",
            text
        )

        # "/" 기준 분리
        parts = [
            p.strip()
            for p in text.split("/")
        ]

        if len(parts) >= 3:

            law_name = parts[0]
            article = parts[1]
            description = "/".join(parts[2:]).strip()

        elif len(parts) == 2:

            law_name = parts[0]
            article = parts[1]
            description = ""

        else:

            law_name = text
            article = ""
            description = ""

        laws.append({
            "number": len(laws) + 1,
            "law": law_name,
            "article": article,
            "description": description
        })

    return laws


# ============================================================
# 5. 조치사항 파싱
# ============================================================

def _parse_actions(lines):

    actions = []

    for line in lines:

        if not line:
            continue

        text = re.sub(
            r"^[①②③④⑤⑥⑦⑧⑨⑩]\s*",
            "",
            line
        )

        text = re.sub(
            r"^\d+[\.\)]\s*",
            "",
            text
        )

        # "즉시 조치: ..."
        match = re.match(
            r"^(즉시\s*조치|개선\s*조치|예방\s*조치)\s*[:：]\s*(.*)$",
            text
        )

        if match:

            category = match.group(1)
            action = match.group(2).strip()

        else:

            category = "기타 조치"
            action = text

        actions.append({
            "number": len(actions) + 1,
            "category": category,
            "action": action
        })

    return actions


# ============================================================
# 6. 일반 문단 추가
# ============================================================

def _add_normal_paragraph(doc, text):

    text = _clean_text(text)

    if not text:
        return

    p = doc.add_paragraph("")

    p.add_run(
        text,
        font="맑은 고딕",
        size=10
    )


# ============================================================
# 7. 섹션 제목 추가
# ============================================================

def _add_section_title(doc, number, title):

    p = doc.add_paragraph("")

    p.add_run(
        f"{number}. {title}",
        bold=True,
        font="맑은 고딕",
        size=14
    )

    return p


# ============================================================
# 8. 표 셀 입력 함수
# ============================================================

def _set_cell(table, row, col, text, bold=False, size=9):

    text = "" if text is None else str(text)

    cell = table.rows[row].cells[col]

    # 셀 내부에 문단 생성
    p = cell.paragraphs[0]

    p.add_run(
        text,
        bold=bold,
        font="맑은 고딕",
        size=size
    )

    return cell


# ============================================================
# 9. 위험요인 표
# ============================================================

def _add_risk_table(doc, risks):

    if not risks:
        _add_normal_paragraph(
            doc,
            "주요 위험요인이 별도로 확인되지 않았습니다."
        )
        return

    # 헤더 + 데이터
    table = doc.add_table(
        rows=len(risks) + 1,
        cols=4
    )

    headers = [
        "번호",
        "주요 위험요인",
        "위험등급",
        "주요 위험내용"
    ]

    for col, header in enumerate(headers):
        _set_cell(
            table,
            0,
            col,
            header,
            bold=True,
            size=9
        )

    for i, risk in enumerate(risks, start=1):

        _set_cell(
            table,
            i,
            0,
            risk["number"]
        )

        _set_cell(
            table,
            i,
            1,
            risk["name"]
        )

        _set_cell(
            table,
            i,
            2,
            risk["grade"],
            bold=True
        )

        _set_cell(
            table,
            i,
            3,
            risk["description"]
        )

    doc.add_paragraph("")


# ============================================================
# 10. 법령 및 기준 표
# ============================================================

def _add_law_table(doc, laws):

    if not laws:
        _add_normal_paragraph(
            doc,
            "관련 법령 및 기준이 별도로 제시되지 않았습니다."
        )
        return

    table = doc.add_table(
        rows=len(laws) + 1,
        cols=4
    )

    headers = [
        "번호",
        "법령·기준",
        "조항",
        "관련 내용"
    ]

    for col, header in enumerate(headers):

        _set_cell(
            table,
            0,
            col,
            header,
            bold=True,
            size=9
        )

    for i, law in enumerate(laws, start=1):

        _set_cell(
            table,
            i,
            0,
            law["number"]
        )

        _set_cell(
            table,
            i,
            1,
            law["law"]
        )

        _set_cell(
            table,
            i,
            2,
            law["article"]
        )

        _set_cell(
            table,
            i,
            3,
            law["description"]
        )

    doc.add_paragraph("")


# ============================================================
# 11. 조치사항 표
# ============================================================

def _add_action_table(doc, actions):

    if not actions:
        _add_normal_paragraph(
            doc,
            "권장 조치사항이 별도로 제시되지 않았습니다."
        )
        return

    table = doc.add_table(
        rows=len(actions) + 1,
        cols=3
    )

    headers = [
        "번호",
        "조치 구분",
        "구체적인 조치사항"
    ]

    for col, header in enumerate(headers):

        _set_cell(
            table,
            0,
            col,
            header,
            bold=True,
            size=9
        )

    for i, action in enumerate(actions, start=1):

        _set_cell(
            table,
            i,
            0,
            action["number"]
        )

        _set_cell(
            table,
            i,
            1,
            action["category"],
            bold=True
        )

        _set_cell(
            table,
            i,
            2,
            action["action"]
        )

    doc.add_paragraph("")


# ============================================================
# 12. HWPX 최종 생성 함수
# ============================================================

def generate_hwpx(title, content):

    current_time = datetime.datetime.now().strftime(
        "%Y-%m-%d %H:%M"
    )

    # --------------------------------------------------------
    # HWPX 문서 생성
    # --------------------------------------------------------

    doc = HwpxDocument.new()

    # --------------------------------------------------------
    # 페이지 설정
    # --------------------------------------------------------

    try:

        section = doc.sections[0]

        # A4 세로
        section.page_width = 210000
        section.page_height = 297000

        # 여백
        section.margin_top = 18000
        section.margin_bottom = 18000
        section.margin_left = 20000
        section.margin_right = 20000

    except Exception:
        # 라이브러리 버전에 따라 페이지 설정 API가 다를 수 있으므로
        # 문서 생성 자체는 계속 진행
        pass

    # --------------------------------------------------------
    # AI 답변 파싱
    # --------------------------------------------------------

    sections = _parse_report_sections(content)

    risks = _parse_risks(
        sections["risks"]
    )

    laws = _parse_laws(
        sections["laws"]
    )

    actions = _parse_actions(
        sections["actions"]
    )

    # ========================================================
    # 표지 / 문서 상단
    # ========================================================

    p = doc.add_paragraph("")

    p.add_run(
        "한국환경공단(K-ECO)",
        bold=True,
        font="맑은 고딕",
        size=16
    )

    p = doc.add_paragraph("")

    p.add_run(
        "수도권서부환경본부",
        bold=True,
        font="맑은 고딕",
        size=13
    )

    # --------------------------------------------------------
    # 보고서 제목
    # --------------------------------------------------------

    p = doc.add_paragraph("")

    p.add_run(
        "기술 자문 및 안전 점검 보고서",
        bold=True,
        font="맑은 고딕",
        size=20
    )

    p = doc.add_paragraph("")

    p.add_run(
        "AI 안전 기술 자문 결과",
        font="맑은 고딕",
        size=11
    )

    doc.add_paragraph("")


    # ========================================================
    # 문서 기본정보 표
    # ========================================================

    info_table = doc.add_table(
        rows=4,
        cols=2
    )

    info_items = [
        ("시행일자", current_time),
        ("대상", "현장 작업 관리자 및 협력업체 임직원"),
        ("문서 제목", title),
        ("작성 부서", "한국환경공단 수도권서부환경본부")
    ]

    for row, (label, value) in enumerate(info_items):

        _set_cell(
            info_table,
            row,
            0,
            label,
            bold=True,
            size=9
        )

        _set_cell(
            info_table,
            row,
            1,
            value,
            size=9
        )

    doc.add_paragraph("")


    # ========================================================
    # 1. 점검 개요
    # ========================================================

    _add_section_title(
        doc,
        1,
        "점검 개요"
    )

    if sections["overview"]:

        for line in sections["overview"]:
            _add_normal_paragraph(
                doc,
                line
            )

    else:

        _add_normal_paragraph(
            doc,
            "AI 안전 기술 자문 요청사항 및 점검 대상에 대한 개요입니다."
        )

    doc.add_paragraph("")


    # ========================================================
    # 2. 주요 위험요인
    # ========================================================

    _add_section_title(
        doc,
        2,
        "주요 위험요인"
    )

    _add_risk_table(
        doc,
        risks
    )


    # ========================================================
    # 3. 관련 법령 및 기준
    # ========================================================

    _add_section_title(
        doc,
        3,
        "관련 법령 및 기준"
    )

    _add_law_table(
        doc,
        laws
    )


    # ========================================================
    # 4. 권장 조치사항
    # ========================================================

    _add_section_title(
        doc,
        4,
        "권장 조치사항"
    )

    _add_action_table(
        doc,
        actions
    )


    # ========================================================
    # 5. 현장 적용 시 유의사항
    # ========================================================

    _add_section_title(
        doc,
        5,
        "현장 적용 시 유의사항"
    )

    if sections["cautions"]:

        for line in sections["cautions"]:

            _add_normal_paragraph(
                doc,
                line
            )

    else:

        _add_normal_paragraph(
            doc,
            "작업 전 관련 위험요인 및 안전조치 이행 여부를 확인하고, "
            "현장 여건에 따라 필요한 추가 안전조치를 실시하여야 합니다."
        )

    doc.add_paragraph("")


    # ========================================================
    # 6. 종합 의견
    # ========================================================

    _add_section_title(
        doc,
        6,
        "종합 의견"
    )

    if sections["opinion"]:

        for line in sections["opinion"]:

            _add_normal_paragraph(
                doc,
                line
            )

    else:

        _add_normal_paragraph(
            doc,
            "상기 위험요인 및 권장 조치사항을 작업 전에 확인하고 "
            "필요한 안전조치를 우선적으로 이행하시기 바랍니다."
        )

    doc.add_paragraph("")


    # ========================================================
    # 7. 행정 및 조치사항
    # ========================================================

    _add_section_title(
        doc,
        7,
        "행정 및 조치사항"
    )

    _add_normal_paragraph(
        doc,
        "상기 위험요소를 현장 작업 전 반드시 숙지하고 "
        "관련 안전조치를 철저히 이행하여 주시기 바랍니다."
    )

    _add_normal_paragraph(
        doc,
        "안전조치가 충분히 이루어지지 않은 상태에서 작업을 진행하지 않도록 "
        "현장 관리자는 작업 전 안전조치 이행 여부를 확인하여야 합니다."
    )

    _add_normal_paragraph(
        doc,
        "현장 안전관리자는 본 보고서의 내용을 바탕으로 "
        "작업 전 안전교육(TBM)을 실시하여 작업자에게 주요 위험요인과 "
        "안전조치 사항을 전달하여 주시기 바랍니다."
    )

    doc.add_paragraph("")
    doc.add_paragraph("")


    # ========================================================
    # 결재 / 발신 명의
    # ========================================================

    p = doc.add_paragraph("")

    p.add_run(
        "한국환경공단",
        bold=True,
        font="맑은 고딕",
        size=12
    )

    p = doc.add_paragraph("")

    p.add_run(
        "수도권서부환경본부",
        bold=True,
        font="맑은 고딕",
        size=11
    )


    # ========================================================
    # 문서 저장
    # ========================================================

    buffer = io.BytesIO()

    doc.save_to_stream(buffer)

    buffer.seek(0)

    return buffer.getvalue()

# --- Base64 이미지 변환 함수 ---
def get_base64_image(image_path):
    try:
        resolved_path = Path(image_path)
        if not resolved_path.is_absolute():
            resolved_path = Path(__file__).resolve().parent / resolved_path
        with open(resolved_path, "rb") as img_file:
            return base64.b64encode(img_file.read()).decode()
    except Exception:
        return ""

