_MOBILE_BACK_GUARD_HTML = '<!doctype html><html><body><script>(() => {\n  "use strict";\n  let w;\n  try { w = window.parent; void w.document.body; } catch (_) { return; }\n  const owner = __BACK_GUARD_OWNER__;\n  const slot = "__kecoMobileBackGuardV1";\n  if (w[slot] && w[slot].owner === owner) { w[slot].syncTabs(); return; }\n  if (w[slot]) w[slot].dispose();\n  const doc = w.document, hist = w.history;\n  const tag = "__kecoBackGuard", marker = "keco-safe-back-v1:" + owner;\n  let observer, syncTimer, busy = false, disposed = false, leaving = false;\n  let exitDialog = null, restoringTab = null;\n  let pendingRevision = null, busyTimer;\n  const trail = [];\n  const state = phase => Object.assign({}, hist.state || {}, {[tag]: {marker, phase}});\n  const rearm = () => {\n    if (!disposed && !leaving) hist.pushState(state("guard"), "", w.location.href);\n  };\n  const mainTabs = () => {\n    const menu = doc.querySelector(".st-key-keco_main_menu");\n    const list = menu && menu.querySelector(\'[role="tablist"]\');\n    return list ? Array.from(list.querySelectorAll(\'[role="tab"]\')) : [];\n  };\n  const activeIndex = () => mainTabs().findIndex(tab => tab.getAttribute("aria-selected") === "true");\n  const syncTabs = () => {\n    const risk = doc.getElementById("keco-risk-navigation"), permit = doc.getElementById("keco-permit-navigation");\n    if (pendingRevision !== null && ((typeof pendingRevision === "string" && pendingRevision.startsWith("ptw:") && permit && "ptw:"+permit.dataset.revision !== pendingRevision) || (typeof pendingRevision === "string" && !pendingRevision.startsWith("ptw:") && risk && risk.dataset.revision !== pendingRevision))) {\n      pendingRevision = null; busy = false; w.clearTimeout(busyTimer);\n    }\n    const index = activeIndex();\n    if (index < 0) return;\n    if (restoringTab !== null) {\n      if (index === restoringTab) restoringTab = null;\n      return;\n    }\n    if (!trail.length || trail[trail.length-1] !== index) trail.push(index);\n    if (trail.length > 100) trail.splice(0, trail.length-100);\n  };\n  const blurInput = () => {\n    const focused = doc.activeElement;\n    if (focused && focused !== doc.body && typeof focused.blur === "function") focused.blur();\n  };\n  const removeDialog = () => {\n    if (!exitDialog) return;\n    const restoreFocus = exitDialog.restoreFocus;\n    exitDialog.element.remove(); exitDialog = null;\n    if (restoreFocus && restoreFocus.isConnected) restoreFocus.focus();\n  };\n  const showExit = (message = "") => {\n    if (exitDialog) return;\n    const overlay = doc.createElement("div");\n    overlay.id = "keco-back-exit-dialog";\n    overlay.style.cssText = "position:fixed;inset:0;z-index:2147483000;background:rgba(15,23,42,.4);display:flex;align-items:center;justify-content:center;padding:20px;";\n    overlay.innerHTML = \'<section role="dialog" aria-modal="true" aria-labelledby="keco-exit-title" style="width:min(100%,380px);box-sizing:border-box;background:#fff;border-radius:16px;padding:24px;color:#1e293b;font-family:Arial,sans-serif;box-shadow:0 14px 48px #0003;">\'\n      + \'<h2 id="keco-exit-title" style="font-size:20px;margin:0 0 12px;">앱에서 나가시겠습니까?</h2>\'\n      + \'<p style="font-size:15px;line-height:1.7;margin:0 0 20px;">처음 화면입니다. 계속 사용하려면 아래 버튼을 누르세요. 저장하지 않은 입력이 있으면 앱에서 나가기 전에 저장해 주세요.</p>\'\n      + \'<button type="button" data-action="continue" style="width:100%;min-height:48px;border:0;border-radius:10px;background:#007a4d;color:#fff;font-size:16px;font-weight:700;cursor:pointer;">앱 계속 사용</button>\'\n      + \'<button type="button" data-action="exit" style="width:100%;min-height:44px;margin-top:10px;border:1px solid #dce5df;border-radius:10px;background:#fff;color:#475569;font-size:15px;cursor:pointer;">앱 나가기</button></section>\';\n    exitDialog = {element:overlay, restoreFocus:doc.activeElement};\n    if (message) {\n      overlay.querySelector("p").textContent = message;\n      overlay.querySelector(\'[data-action="exit"]\').style.display = "none";\n    }\n    doc.body.appendChild(overlay);\n    overlay.querySelector(\'[data-action="continue"]\').addEventListener("click", removeDialog);\n    overlay.querySelector(\'[data-action="exit"]\').addEventListener("click", () => {\n      removeDialog(); leaving = true; hist.back();\n      // A standalone app may have no earlier page to leave for.\n      w.setTimeout(() => {\n        if (!disposed && leaving) {\n          leaving = false; rearm();\n          showExit("이 기기에서는 휴대폰 홈 버튼 또는 브라우저 닫기를 이용해 앱에서 나갈 수 있습니다. 계속 사용하려면 아래 버튼을 누르세요.");\n        }\n      }, 900);\n    });\n    overlay.querySelector(\'[data-action="continue"]\').focus();\n  };\n  const onKey = event => {\n    if (!exitDialog) return;\n    if (event.key === "Escape") { event.preventDefault(); removeDialog(); }\n    if (event.key === "Tab") {\n      const buttons = Array.from(exitDialog.element.querySelectorAll("button"));\n      const target = event.shiftKey ? buttons[buttons.length-1] : buttons[0];\n      if ((event.shiftKey && doc.activeElement === buttons[0]) || (!event.shiftKey && doc.activeElement === buttons[buttons.length-1])) {\n        event.preventDefault(); target.focus();\n      }\n    }\n  };\n  const goInside = () => {\n    if (disposed || leaving) return;\n    syncTabs();\n    const tabs = mainTabs(), index = activeIndex();\n    const riskMarker = doc.getElementById("keco-risk-navigation");\n    if (index >= 0 && tabs[index].textContent.trim() === "위험성평가" && riskMarker && riskMarker.dataset.back === "yes") {\n      const button = doc.querySelector(".st-key-keco_hardware_back button");\n      if (button && !button.disabled) {\n        pendingRevision = riskMarker.dataset.revision;\n        button.click();\n        busyTimer = w.setTimeout(() => { pendingRevision = null; busy = false; }, 15000);\n        return;\n      }\n    }\n    const permitMarker = doc.getElementById("keco-permit-navigation");\n    if (index >= 0 && tabs[index].textContent.trim() === "작업허가제" && permitMarker && permitMarker.dataset.back === "yes") {\n      const button = doc.querySelector(".st-key-ptw_back_frame button");\n      if (button && !button.disabled) {\n        pendingRevision = "ptw:"+permitMarker.dataset.revision;\n        button.click();\n        busyTimer = w.setTimeout(() => { pendingRevision = null; busy = false; }, 15000);\n        return;\n      }\n    }\n    const homeView = doc.getElementById("keco-workstation-view");\n    if (index === 0 && homeView && homeView.dataset.registration === "yes" && w.matchMedia("(min-width:769px)").matches) {\n      const homeButton = doc.querySelector(".st-key-ws_return_home button");\n      if (homeButton && !homeButton.disabled) { homeButton.click(); return; }\n    }\n    if (trail.length > 1) {\n      trail.pop(); restoringTab = trail[trail.length-1];\n      if (tabs[restoringTab]) tabs[restoringTab].click();\n      else restoringTab = null;\n      return;\n    }\n    if (index > 0 && tabs[0]) {\n      trail.splice(0, trail.length, 0); restoringTab = 0; tabs[0].click(); return;\n    }\n    showExit();\n  };\n  const onPop = () => {\n    if (disposed) return;\n    if (leaving) { hist.back(); return; }\n    rearm(); // Re-arm synchronously even when Back is pressed repeatedly.\n    syncTabs();\n    if (exitDialog) { removeDialog(); return; }\n    if (busy) return;\n    busy = true; blurInput();\n    // Blur submits the current Streamlit text widget before navigation.\n    w.setTimeout(() => { goInside(); if (pendingRevision === null) w.setTimeout(() => { busy = false; }, 250); }, 160);\n  };\n  const dispose = () => {\n    disposed = true; w.removeEventListener("popstate", onPop);\n    doc.removeEventListener("keydown", onKey);\n    if (observer) observer.disconnect();\n    w.clearTimeout(syncTimer); w.clearTimeout(busyTimer); removeDialog();\n  };\n  const existing = hist.state && hist.state[tag];\n  if (!existing || existing.marker !== marker) {\n    hist.replaceState(state("anchor"), "", w.location.href); rearm();\n  } else if (existing.phase !== "guard") rearm();\n  w.addEventListener("popstate", onPop);\n  doc.addEventListener("keydown", onKey);\n  observer = new w.MutationObserver(records => {\n    if (records.some(record => record.attributeName === "aria-selected")) syncTabs();\n    w.clearTimeout(syncTimer); syncTimer = w.setTimeout(syncTabs, 30);\n  });\n  observer.observe(doc.body, {subtree:true, childList:true, attributes:true, attributeFilter:["aria-selected", "data-revision"]});\n  w[slot] = {owner, syncTabs, dispose}; syncTabs();\n})();\n</script></body></html>'

def render_mobile_back_guard(actor):
    import hashlib
    owner = hashlib.sha256(str(actor).encode('utf-8')).hexdigest()[:24]
    script = _MOBILE_BACK_GUARD_HTML.replace('__BACK_GUARD_OWNER__', json.dumps(owner))
    with st.container(key='keco_back_guard_frame'):
        components.html(script, height=0, scrolling=False)
    st.html('<style>.st-key-keco_back_guard_frame{display:none!important;}</style>')

