def report_history_reset_detail(owner):
    st.session_state.pop('report_history_purge_request:'+owner, None)
    for key in list(st.session_state):
        if key in ('report_history_open:'+owner, 'report_history_preview:'+owner) or str(key).startswith('report_history_confirm:'+owner+':'):
            st.session_state.pop(key, None)


def report_history_reset_selection(owner):
    st.session_state.pop('report_history_selected:'+owner, None)
    st.session_state.pop('report_history_trash_selected:'+owner, None)
    report_history_reset_detail(owner)


def report_history_select(owner, selection, checked_key=None, trashed=False):
    owner = report_history_identity(owner)
    if trashed:
        key = 'report_history_trash_selected:'+owner
        selected = list(st.session_state.get(key, []))
        checked = st.session_state.get(checked_key, False) if checked_key is not None else selection not in selected
        if checked and selection not in selected:
            selected.append(selection)
        elif not checked and selection in selected:
            selected.remove(selection)
        st.session_state[key] = selected
    else:
        if checked_key is not None and not st.session_state.get(checked_key):
            selection = None
        st.session_state['report_history_selected:'+owner] = selection
    report_history_reset_detail(owner)


def report_history_select_all(owner, tokens, checked_key):
    owner = report_history_identity(owner)
    if st.session_state.get('report_history_view:'+owner) != '휴지통':
        return
    st.session_state['report_history_trash_selected:'+owner] = list(tokens) if st.session_state.get(checked_key) else []
    report_history_reset_detail(owner)


def report_history_selection_changed(owner):
    owner = report_history_identity(owner)
    report_history_reset_detail(owner)


def report_history_toggle_open(owner, selection):
    owner = report_history_identity(owner)
    if not selection or st.session_state.get('report_history_selected:'+owner) != selection:
        return
    key = 'report_history_open:'+owner
    if st.session_state.get(key) == selection:
        st.session_state.pop(key, None)
    else:
        st.session_state[key] = selection
    st.session_state.pop('report_history_preview:'+owner, None)


def report_history_confirmation_key(owner, selection, *, permanent=False):
    purpose = 'purge:' if permanent else 'trash:'
    return 'report_history_confirm:'+str(owner)+':'+purpose+hashlib.sha256(str(selection).encode()).hexdigest()


def report_history_clear_exports(owner, targets):
    report_history_reset_selection(owner)
    inspection = any(source == 'inspection' for source, _ in targets)
    if inspection:
        for key in ('inspection_report_key', 'inspection_report_archived_key', 'inspection_report_bytes',
                    'inspection_report_name', 'inspection_pdf_bytes'):
            st.session_state.pop(key, None)
    if inspection or any(source == 'generated' and str(report_id).startswith('batch:') for source, report_id in targets):
        for key in ('batch_key', 'batch_output', 'inspection_batch_selection'):
            st.session_state.pop(key, None)
    if any(source == 'generated' and str(report_id).startswith('risk:') for source, report_id in targets):
        st.session_state.pop('ra_output', None)
        st.session_state.pop('ra_last_saved_sig', None)


def report_history_remove_trashed(db, tables, owner, source, report_id, table):
    keys = set()
    refs = None
    if source == 'inspection':
        if 'report_files' in tables:
            refs = db.execute('SELECT hex(hwpx),hex(pdf) FROM report_files WHERE id=?', (report_id,)).fetchone()
        encoded = db.execute('SELECT payload FROM reports WHERE id=? AND owner=?', (report_id, owner)).fetchone()[0]
        try:
            payload = json.loads(encoded)
            items = payload.values() if isinstance(payload, dict) else []
            for item in items:
                if not isinstance(item, dict): continue
                for field in ('before_files', 'after_files'):
                    values = item.get(field, [])
                    if not isinstance(values, list): continue
                    for value in values:
                        if isinstance(value, str) and value.startswith(PHOTO_REF):
                            key = value[len(PHOTO_REF):]
                            if re.fullmatch(r'images/[0-9a-f]{64}\.[a-z0-9]+', key): keys.add(key)
        except (ValueError, TypeError):
            pass
    else:
        refs = db.execute('SELECT hex(hwpx),hex(pdf) FROM '+table+' WHERE id=? AND owner=?', (report_id, owner)).fetchone()
    for encoded in refs or ():
        try:
            raw = bytes.fromhex(encoded or '')
            if not raw.startswith(b'KECO-NHN-BLOB-V1:'): continue
            key = raw[len(b'KECO-NHN-BLOB-V1:'):].decode('ascii')
        except (ValueError, UnicodeError):
            continue
        if re.fullmatch(r'files/[0-9a-f]{64}\.[a-z0-9]+', key): keys.add(key)
    for key in keys:
        db.execute('INSERT OR IGNORE INTO risk_file_cleanup VALUES (?)', (key,))
    if source == 'inspection' and 'report_files' in tables:
        db.execute('DELETE FROM report_files WHERE id=?', (report_id,))
    if source == 'generated':
        if 'generated_report_info' in tables:
            db.execute('DELETE FROM generated_report_info WHERE id=? AND owner=?', (report_id, owner))
        if 'risk_assessment_artifacts' in tables:
            db.execute('DELETE FROM risk_assessment_artifacts WHERE generated_id=? AND owner=?', (report_id, owner))
    db.execute('DELETE FROM '+table+' WHERE id=? AND owner=?', (report_id, owner))


def report_history_trash_batch(owner, targets, *, permanent=False):
    """Validate all selected reports and apply one transaction to the trash."""
    owner = report_history_identity(owner)
    items = tuple(dict.fromkeys((source, str(report_id)) for source, report_id in targets))
    if not items:
        raise ValueError('휴지통에서 처리할 리포트를 선택해 주세요.')
    table_by_source = {'inspection':'reports', 'generated':'generated_reports', 'uploaded':'personal_report_imports'}
    denied = '본인의 휴지통에 있는 리포트만 '+('완전삭제' if permanent else '복원')+'할 수 있습니다.'
    db = inspection_store()
    compacted = True
    try:
        with db:
            db.execute('BEGIN IMMEDIATE')
            tables = report_history_tables(db)
            if 'report_trash' not in tables:
                raise PermissionError(denied)
            verified = []
            for source, report_id in items:
                table = table_by_source.get(source)
                if table not in tables or not db.execute('SELECT 1 FROM '+table+' WHERE id=? AND owner=?',
                                                         (report_id, owner)).fetchone():
                    raise PermissionError(denied)
                marker = db.execute('SELECT 1 FROM report_trash WHERE source=? AND report_id=? AND owner=?',
                                    (source, report_id, owner)).fetchone()
                if not marker:
                    raise PermissionError(denied)
                verified.append((source, report_id, table))
            if permanent:
                db.execute('CREATE TABLE IF NOT EXISTS risk_file_cleanup (object_key TEXT PRIMARY KEY)')
            for source, report_id, table in verified:
                if permanent:
                    report_history_remove_trashed(db, tables, owner, source, report_id, table)
                db.execute('DELETE FROM report_trash WHERE source=? AND report_id=? AND owner=?',
                           (source, report_id, owner))
        if permanent:
            try:
                db.execute('VACUUM')
            except Exception:
                compacted = False
    finally:
        db.close()
    pending = 0
    if permanent:
        try:
            pending = ra_cleanup_files()
        except Exception:
            pending = -1
    return dict(count=len(items), compacted=compacted, cleanup_pending=pending)


def report_history_purge(owner, source, report_id):
    return report_history_trash_batch(owner, [(source, report_id)], permanent=True)


def report_history_request_purge(owner, selection):
    owner = report_history_identity(owner)
    if (st.session_state.get('report_history_view:'+owner) == '휴지통' and selection
            and tuple(st.session_state.get('report_history_trash_selected:'+owner, ())) == selection):
        report_history_reset_detail(owner)
        st.session_state['report_history_purge_request:'+owner] = selection


def report_history_apply_trash_selection(owner, selection, permanent=False):
    owner = str(owner)
    error_key = 'report_history_error:'+owner
    if (st.session_state.get('report_history_view:'+owner) != '휴지통' or not selection
            or tuple(st.session_state.get('report_history_trash_selected:'+owner, ())) != selection):
        st.session_state[error_key] = '휴지통에서 처리할 리포트를 다시 선택해 주세요.'
        return
    if permanent and (st.session_state.get('report_history_purge_request:'+owner) != selection
            or not st.session_state.get(report_history_confirmation_key(owner, selection, permanent=True))):
        st.session_state[error_key] = '선택한 리포트의 완전삭제 확인란을 체크해 주세요.'
        return
    try:
        targets = [json.loads(token) for token in selection]
        result = report_history_trash_batch(owner, targets, permanent=permanent)
    except (StorageError, PermissionError, ValueError, TypeError) as exc:
        st.session_state[error_key] = str(exc)
        return
    except Exception:
        action = '완전삭제' if permanent else '복원'
        st.session_state[error_key] = action+' 결과를 확인하지 못했습니다. 목록을 새로고침해 주세요.'
        return
    report_history_clear_exports(owner, targets)
    action = '완전삭제' if permanent else '복원'
    message = f'리포트 {result["count"]}건을 {action}했습니다.'
    if permanent:
        st.session_state['report_history_cleanup_pending:'+owner] = result['cleanup_pending']
        if not result['compacted']:
            message += ' 기록은 삭제했으며 저장 공간 압축은 확인이 필요합니다.'
    elif any(source == 'inspection' for source, _ in targets):
        message += ' 점검 현황 집계와 취합 대상에 다시 반영됩니다.'
    st.session_state['report_history_notice:'+owner] = message
    st.session_state.pop(error_key, None)
    st.session_state['report_history_reload:'+owner] = True


def report_history_retry_cleanup(owner):
    owner = report_history_identity(owner)
    try:
        pending = ra_cleanup_files()
        st.session_state['report_history_cleanup_pending:'+owner] = pending
        st.session_state['report_history_notice:'+owner] = ('남은 파일 정리를 마쳤습니다.' if pending == 0 else '일부 파일 정리가 남아 있습니다. 다시 시도해 주세요.')
    except Exception:
        st.session_state['report_history_error:'+owner] = '파일 정리를 완료하지 못했습니다. 저장소 연결·삭제 권한을 확인해 주세요.'


def render_report_history_rows(owner, shown, selection, *, trashed=False):
    widths = [.85 if trashed else .4, 1.5, 3.3, 1, 1]
    selected_tokens = set(selection) if trashed else {selection}
    with st.container(key='report_history_rows'):
        with st.container(key='report_history_trash_header' if trashed else 'report_history_table_header'):
            columns = st.columns(widths, vertical_alignment='center')
            if trashed:
                tokens = tuple(json.dumps([row['source'], row['id']]) for row in shown)
                all_key = 'report_history_trash_all:'+owner
                st.session_state[all_key] = bool(tokens) and set(tokens).issubset(selected_tokens)
                columns[0].checkbox('선택', key=all_key, help='현재 목록의 리포트를 모두 선택하거나 해제합니다.',
                                    on_change=report_history_select_all, args=(owner, tokens, all_key))
            else:
                columns[0].markdown('**선택**')
            for column, label in zip(columns[1:], ['작성일', '현장 / 리포트', '종류', '저장 파일']):
                column.markdown('**'+label+'**')
        for row in shown:
            token = json.dumps([row['source'], row['id']])
            digest = hashlib.sha256((owner+token).encode()).hexdigest()[:20]
            selected = token in selected_tokens
            row_key = 'report_history_row_'+('active_' if selected else '')+digest
            check_key = 'report_history_rowchecked:'+owner+':'+digest
            st.session_state[check_key] = selected
            with st.container(key=row_key):
                check, date, title, kind, files = st.columns(widths, vertical_alignment='center')
                with check:
                    st.checkbox('리포트 선택 · '+(row['site'] or row['title'])+' · '+row['id'][-6:], key=check_key,
                                label_visibility='collapsed', on_change=report_history_select, args=(owner, token, check_key, trashed))
                with date:
                    st.button(row['created'].replace('T', ' ')[:19] or '날짜 미확인', key='report_history_rowdate:'+digest,
                              on_click=report_history_select, args=(owner, token, None, trashed), width='stretch')
                    if trashed:
                        st.caption('삭제 '+row.get('deleted_at', '').replace('T', ' ')[:16])
                with title:
                    st.button(row['site'] or row['title'], key='report_history_rowtitle:'+digest,
                              on_click=report_history_select, args=(owner, token, None, trashed), width='stretch')
                    st.caption(row['title'])
                kind.write(row['kind'])
                files.caption(' · '.join(label for flag, label in ((row['has_hwpx'], '한글'), (row['has_pdf'], 'PDF')) if flag) or '점검 내용·사진')


def render_report_history_management(owner, choices, selection, *, trashed=False):
    st.divider()
    if trashed:
        with st.container(key='report_history_trash_actions'):
            restore, purge = st.columns(2, gap='small')
            restore.button('선택한 리포트 복원', key='report_history_untrash:'+owner, type='secondary',
                           disabled=not selection, width='stretch',
                           on_click=report_history_apply_trash_selection, args=(owner, selection))
            purge.button('선택한 리포트 완전삭제', key='report_history_request_purge:'+owner, type='secondary',
                         disabled=not selection, width='stretch',
                         on_click=report_history_request_purge, args=(owner, selection))
        if selection and st.session_state.get('report_history_purge_request:'+owner) == selection:
            st.warning(f'선택한 리포트 {len(selection)}건과 저장 파일을 완전삭제합니다. 삭제한 리포트는 복원할 수 없습니다.')
            if len(selection) == 1:
                row = choices[selection[0]]
                st.write('삭제 대상: '+(row['site'] or row['title'])+' · '+row['created'].replace('T', ' ')[:19]+' · '+row['id'][-6:])
            confirmed = st.checkbox('선택한 리포트와 저장 파일을 복원할 수 없음을 확인했습니다.',
                                    key=report_history_confirmation_key(owner, selection, permanent=True))
            execute, cancel = st.columns(2, gap='small')
            execute.button('완전삭제 실행', key='report_history_purge:'+owner, type='primary',
                           disabled=not confirmed, width='stretch',
                           on_click=report_history_apply_trash_selection, args=(owner, selection, True))
            cancel.button('취소', key='report_history_cancel_purge:'+owner, width='stretch',
                          on_click=report_history_reset_detail, args=(owner,))
        return
    render_report_history_import(owner)
    st.selectbox('조회·삭제할 리포트', list(choices), index=None,
                 placeholder='위 목록에서 선택하거나 여기에서 리포트를 선택하세요', disabled=not choices,
                 format_func=lambda token: f"{choices[token]['created'].replace('T',' ')[:19] or '날짜 미확인'} | {choices[token]['site'] or choices[token]['title']} | {choices[token]['kind']} | {choices[token]['id'][-6:]}",
                 key='report_history_selected:'+owner, on_change=report_history_selection_changed, args=(owner,))
    with st.expander('선택한 리포트 삭제'):
        st.caption('선택한 리포트를 휴지통으로 옮깁니다. 잘못 삭제했다면 휴지통에서 복원할 수 있습니다.')
        confirmed = st.checkbox('선택한 리포트를 휴지통으로 옮기는 데 동의합니다.',
                                key=report_history_confirmation_key(owner, selection), disabled=not selection)
        st.button('휴지통으로 이동', key='report_history_trash:'+owner, disabled=not (selection and confirmed),
                  on_click=report_history_trash_action, args=(owner, selection, False))


def render_report_history_detail(owner, row, selection):
    try:
        detail = report_history_get(owner,row["source"],row["id"])
    except (StorageError, PermissionError, ValueError) as exc:
        st.error(str(exc))
        return
    filename = re.sub(r'[\\/:*?"<>|\x00-\x1f]',"_",row["title"]+"_"+row["site"])[:100] + "_" + row["id"][-6:]
    if detail["hwpx"]:
        st.download_button("저장한 한글 내려받기",detail["hwpx"],filename+".hwpx","application/vnd.hancom.hwpx",key="report_history_hwpx_download:"+owner,on_click="ignore",width="stretch")
    if detail["pdf"]:
        st.download_button("저장한 PDF 내려받기",detail["pdf"],filename+".pdf","application/pdf",key="report_history_pdf_download:"+owner,on_click="ignore",width="stretch")
    if detail["pdf"]:
        if st.button("PDF 화면에서 보기",key="report_history_preview_button:"+owner,width="stretch"):
            st.session_state["report_history_preview:"+owner] = selection
        if st.session_state.get("report_history_preview:"+owner) == selection:
            page_key = "report_history_pdf_page:"+owner+":"+selection
            try:
                picture,total,page = report_history_pdf_page(detail["pdf"],st.session_state.get(page_key,1))
                if st.session_state.get(page_key,page) != page:
                    st.session_state[page_key] = page
                st.number_input("PDF 페이지",min_value=1,max_value=total,value=page,step=1,key=page_key)
                st.image(picture,caption=f"PDF {page} / {total}페이지",width="stretch")
            except Exception:
                st.warning("PDF 미리보기를 만들지 못했습니다. 파일을 내려받아 확인해 주세요.")
    if row["source"] == "inspection":
        if not detail["pdf"] or not detail["hwpx"]:
            st.caption("예전 기록에 없는 보고서 파일은 저장된 사진과 내용으로 다시 만들 수 있습니다. 다시 만든 파일에는 현재 생성 시간이 표시됩니다.")
            if st.button("저장된 내용으로 보고서 다시 만들기",key="report_history_restore:"+owner,width="stretch"):
                try:
                    report_history_restore_files(owner,row["id"])
                    st.session_state["report_history_notice:" + owner] = "저장된 내용으로 보고서 파일을 다시 만들었습니다."
                    st.rerun()
                except Exception:
                    st.error("보고서를 다시 만들지 못했습니다. 저장한 사진과 문서 생성 설정을 확인해 주세요.")
        for index,item in detail["payload"].items():
            with st.expander(f"점검 항목 {index}",expanded=True):
                for field,label,description in (("before_files","조치 전","desc_before"),("after_files","조치 후","desc_after")):
                    st.markdown("**"+label+"**")
                    st.text(str(item.get(description,"")) or "기록된 설명이 없습니다.")
                    for number,value in enumerate(item.get(field,[]),1):
                        try:
                            st.image(inspection_photo_bytes(value),caption=f"{label} 사진 {number}",width="stretch")
                        except Exception:
                            st.warning("저장된 사진을 읽지 못했습니다. 원본 자료와 저장소 연결을 확인해 주세요.")
                if item.get("ai_analysis"):
                    st.markdown("**저장한 AI 분석**")
                    st.text(str(item["ai_analysis"]))



def render_report_history(owner):
    owner = report_history_identity(owner)
    st.markdown(REPORT_HISTORY_CSS, unsafe_allow_html=True)
    with st.container(key='report_history_panel'):
        with st.container(key='report_history_toolbar'):
            heading, refresh = st.columns([1, .2], vertical_alignment='center')
            heading.subheader('내 리포트')
            with refresh:
                st.button('새로고침', icon=':material/refresh:', help='리포트 목록 새로고침',
                          key='report_history_refresh:'+owner, width='content')
        st.caption('본인이 저장한 리포트를 조회하거나 PDF·한글 파일을 다시 내려받습니다.')
        notice = st.session_state.pop('report_history_notice:'+owner, None)
        if notice: st.success(notice)
        error = st.session_state.pop('report_history_error:'+owner, None)
        if error: st.error(error)
        if st.session_state.get('report_history_cleanup_pending:'+owner, 0) != 0:
            st.warning('리포트 기록은 삭제했으며 일부 저장 파일 정리가 남아 있습니다.')
            st.button('남은 파일 정리 다시 시도', key='report_history_cleanup_retry:'+owner,
                      on_click=report_history_retry_cleanup, args=(owner,))
        view = st.radio('리포트 보관함', ['보관 중', '휴지통'], horizontal=True, key='report_history_view:'+owner,
                        on_change=report_history_reset_selection, args=(owner,))
        trashed = view == '휴지통'
        if trashed:
            st.caption('휴지통의 안전점검 보고서는 점검 현황 집계와 취합 대상에서 제외됩니다. 복원하면 다시 반영됩니다.')
        try:
            records = report_history_list(owner, trashed=trashed)
        except StorageError as exc:
            st.error(str(exc))
            return
        shown = []
        if records:
            left, right = st.columns(2)
            search = left.text_input('리포트 검색', placeholder='현장명·리포트 제목', key='report_history_search:'+owner).strip().casefold()
            period = right.selectbox('리포트 기간', ['전체 기간', '최근 30일', '최근 90일'], key='report_history_period:'+owner)
            sites = ['전체 현장']+sorted({row['site'] for row in records if row['site']})
            site_key = 'report_history_site:'+owner
            if st.session_state.get(site_key) not in sites: st.session_state[site_key] = '전체 현장'
            site = st.selectbox('리포트 현장', sites, key=site_key)
            today = datetime.datetime.now(ZoneInfo('Asia/Seoul')).date()
            threshold = (today-datetime.timedelta(days=29 if period == '최근 30일' else 89)).isoformat()
            shown = [row for row in records if (site == '전체 현장' or row['site'] == site)
                     and (not search or search in (row['title']+' '+row['site']+' '+row['dept']).casefold())
                     and (period == '전체 기간' or threshold <= row['created'][:10] <= today.isoformat())]
        choices = {json.dumps([row['source'], row['id']]):row for row in shown}
        if trashed:
            select_key = 'report_history_trash_selected:'+owner
            selected = set(st.session_state.get(select_key, ()))
            selection = tuple(token for token in choices if token in selected)
            st.session_state[select_key] = list(selection)
        else:
            select_key = 'report_history_selected:'+owner
            selection = st.session_state.get(select_key)
            if selection not in choices:
                selection = None
                st.session_state[select_key] = None
        scope = (trashed, selection, tuple(choices) if trashed else ())
        if st.session_state.get('report_history_selection_scope:'+owner) != scope:
            report_history_reset_detail(owner)
            st.session_state['report_history_selection_scope:'+owner] = scope
        if shown:
            count = len(selection) if trashed else int(selection is not None)
            st.caption(f'리포트 {len(shown)}건 · 선택 {count}건')
            render_report_history_rows(owner, shown, selection, trashed=trashed)
        else:
            st.info('조건에 맞는 리포트가 없습니다. 기간이나 검색어를 변경해 주세요.' if records else
                    '휴지통이 비어 있습니다.' if trashed else '보관 중인 리포트가 없습니다. 아래에서 예전 파일을 가져올 수 있습니다.')
        if not trashed and shown:
            opened = bool(selection and st.session_state.get('report_history_open:'+owner) == selection)
            st.button('선택한 리포트 닫기' if opened else '선택한 리포트 열기', key='report_history_open_button:'+owner,
                      disabled=not selection, on_click=report_history_toggle_open, args=(owner, selection))
            if opened:
                render_report_history_detail(owner, choices[selection], selection)
        render_report_history_management(owner, choices, selection, trashed=trashed)



# --- 점검 건 중심 업무 흐름: 저장 / 조치 / 승인 / 불변 보고서 ---
def case_now():
    return datetime.datetime.now(ZoneInfo('Asia/Seoul')).isoformat(timespec='seconds')


def case_new_registration():
    # 기존 자료는 DB에 유지하고 새 등록 화면만 비웁니다.
    for key in list(st.session_state):
        if str(key).startswith(('case_capture:', 'desc_before_', 'desc_after_', 'before_imgs_',
                                'after_imgs_', 'before_cam_', 'after_cam_', 'mode_b_', 'mode_a_',
                                'before_analysis_fingerprint_', 'inspection_report_', 'inspection_pdf_')):
            del st.session_state[key]
    st.session_state.item_count = 1
    st.session_state.ai_results = {}
    st.session_state.pop("_perf_private_cache", None)
    st.session_state.easy_reset_confirmed = False


def case_db():
    import sqlite3
    db = inspection_store()
    db.row_factory = sqlite3.Row
    db.execute('''CREATE TABLE IF NOT EXISTS safety_cases (
        id TEXT PRIMARY KEY, owner TEXT NOT NULL, dept TEXT NOT NULL, site TEXT NOT NULL,
        inspected TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL,
        status TEXT NOT NULL, assignee TEXT NOT NULL DEFAULT '', due TEXT NOT NULL DEFAULT '',
        revision INTEGER NOT NULL DEFAULT 1, payload TEXT NOT NULL)''')
    db.execute('''CREATE TABLE IF NOT EXISTS safety_case_events (
        seq INTEGER PRIMARY KEY AUTOINCREMENT, case_id TEXT, actor TEXT, at TEXT, action TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS safety_case_versions (
        id TEXT PRIMARY KEY, case_id TEXT, kind TEXT, created TEXT, revision INTEGER,
        payload TEXT, hwpx BLOB, pdf BLOB, UNIQUE(case_id,kind,revision))''')
    db.commit()
    return db


def case_pack(items):
    result = {}
    for idx, item in items.items():
        row = {key: str(item.get(key, '')) for key in ('desc_before','desc_after','ai_analysis')}
        for field in ('before_files','after_files'):
            row[field] = [inspection_photo_pack(f) for f in item.get(field, [])]
        result[str(idx)] = row
    return result


def case_unpack(payload):
    result = json.loads(payload) if isinstance(payload, str) else json.loads(json.dumps(payload))
    for row in result.values():
        for field in ('before_files','after_files'):
            row[field] = [inspection_photo_stream(value) for value in row.get(field, [])]
    return result


def case_get(case_id, actor):
    db = case_db()
    try:
        row = db.execute('SELECT * FROM safety_cases WHERE id=? AND (owner=? OR assignee=?)',
                         (case_id, str(actor), str(actor))).fetchone()
        if not row:
            raise PermissionError('이 점검 건에 접근할 권한이 없습니다.')
        result = dict(row)
        result['site'] = canonical_site_label(result.get('site', ''))
        return result
    finally:
        db.close()


def case_create(owner, dept, site, items):
    import uuid
    if st.secrets.get('user_roles', {}).get(str(owner)) == 'contractor':
        raise PermissionError('조치 담당자 계정은 배정된 건의 조치 결과만 등록할 수 있습니다.')
    payload = case_pack(items)
    if not payload:
        raise ValueError('저장할 항목이 없습니다.')
    now = case_now()
    key = 'SI-' + now[:10].replace('-', '') + '-' + uuid.uuid4().hex[:12].upper()
    db = case_db()
    try:
        with db:
            db.execute('INSERT INTO safety_cases (id,owner,dept,site,inspected,created,updated,status,payload) VALUES (?,?,?,?,?,?,?,?,?)',
                       (key, str(owner), dept, site, now[:10], now, now, '작성 중', json.dumps(payload, ensure_ascii=False)))
            db.execute('INSERT INTO safety_case_events(case_id,actor,at,action) VALUES (?,?,?,?)',
                       (key, str(owner), now, '점검 생성'))
    finally:
        db.close()
    return key


def case_save(case_id, actor, revision, payload, status=None, assignee=None, due=None):
    """서버 측 권한·상태 검사와 동시 수정 충돌 방지. 완료본은 수정 불가."""
    row = case_get(case_id, actor)
    owner = row['owner'] == str(actor)
    if row['status'] == '조치 완료':
        raise ValueError('완료 건은 수정할 수 없습니다. 보존된 보고서를 사용해 주세요.')
    old = json.loads(row['payload'])
    if not owner:
        if row['status'] != '조치 요청' or status not in (None, '조치 요청', '확인 대기'):
            raise PermissionError('지정 담당자는 조치 요청 상태에서만 결과를 등록할 수 있습니다.')
        if set(old) != set(payload):
            raise PermissionError('점검 항목을 변경할 수 없습니다.')
        for idx in old:
            for key in ('desc_before','before_files','ai_analysis'):
                if old[idx].get(key) != payload[idx].get(key):
                    raise PermissionError('조치 전 자료를 변경할 수 없습니다.')
        if assignee is not None or due is not None:
            raise PermissionError('담당자와 기한은 감독관만 지정할 수 있습니다.')
    next_status = status or row['status']
    allowed = {'작성 중': {'작성 중','조치 요청'}, '조치 요청': {'조치 요청','확인 대기'},
               '확인 대기': {'확인 대기','조치 요청','조치 완료'}}
    if next_status not in allowed.get(row['status'], set()):
        raise ValueError('허용되지 않은 상태 변경입니다.')
    if next_status in ('확인 대기','조치 완료'):
        if not all(v.get('after_files') and v.get('desc_after','').strip() for v in payload.values()):
            raise ValueError('모든 항목에 조치 후 사진과 설명을 등록해 주세요.')
    if next_status == '조치 완료' and not owner:
        raise PermissionError('감독관만 조치 완료를 승인할 수 있습니다.')
    assignee = row['assignee'] if assignee is None else str(assignee)
    due = row['due'] if due is None else due
    if assignee and assignee not in st.secrets.get('passwords', {}):
        raise ValueError('등록된 로그인 계정만 조치 담당자로 지정할 수 있습니다.')
    if due:
        datetime.date.fromisoformat(due)
    encoded = json.dumps(payload, ensure_ascii=False)
    db = case_db()
    try:
        with db:
            changed = db.execute('UPDATE safety_cases SET payload=?,status=?,assignee=?,due=?,updated=?,revision=revision+1 WHERE id=? AND revision=?',
                                 (encoded,next_status,assignee,due,case_now(),case_id,revision))
            if changed.rowcount != 1:
                raise ValueError('다른 창에서 수정했습니다. 점검 건을 다시 열어 주세요.')
            db.execute('INSERT INTO safety_case_events(case_id,actor,at,action) VALUES (?,?,?,?)',
                       (case_id,str(actor),case_now(),f'{row["status"]} → {next_status} / 자료 저장'))
    finally:
        db.close()




def case_report(case_id, actor, kind):
    import uuid
    row = case_get(case_id,actor)
    if row['owner'] != str(actor):
        raise PermissionError('감독관만 보고서를 확정할 수 있습니다.')
    if kind not in ('최초점검','조치완료'):
        raise ValueError('보고서 종류 오류')
    if kind == '조치완료' and row['status'] != '조치 완료':
        raise ValueError('감독관 확인 완료 후 완료 보고서를 생성하세요.')
    db = case_db()
    try:
        previous = db.execute('SELECT id FROM safety_case_versions WHERE case_id=? AND kind=? AND revision=?',
                              (case_id,kind,row['revision'])).fetchone()
        if previous:
            return previous['id']
        payload = json.loads(row['payload'])
        if kind == '최초점검':
            for item in payload.values():
                item['after_files'] = []
                item['desc_after'] = '최초 점검 시 조치 결과 미포함'
        items = case_unpack(payload)
        metadata = f'{row["site"]} / {case_id} / 점검일 {row["inspected"]}'
        title = '현장 안전점검 보고서' if kind == '최초점검' else '현장 안전점검 및 조치 결과 보고서'
        hwpx = generate_inspection_hwpx(row['dept'],metadata,actor,items,report_title=title)
        pdf = generate_inspection_pdf(row['dept'],metadata,actor,items,report_title=title)
        key = uuid.uuid4().hex
        with db:
            db.execute('BEGIN IMMEDIATE')
            current = db.execute('SELECT revision FROM safety_cases WHERE id=?',(case_id,)).fetchone()
            if current['revision'] != row['revision']:
                raise ValueError('보고서 생성 중 내용이 변경됐습니다. 다시 생성해 주세요.')
            db.execute('INSERT OR IGNORE INTO safety_case_versions VALUES (?,?,?,?,?,?,?,?)',
                       (key,case_id,kind,case_now(),row['revision'],json.dumps(payload,ensure_ascii=False),hwpx,pdf))
            saved = db.execute('SELECT id FROM safety_case_versions WHERE case_id=? AND kind=? AND revision=?',
                               (case_id,kind,row['revision'])).fetchone()['id']
        return saved
    finally:
        db.close()


def case_export(owner, version_ids, include_photos=False):
    import zipfile, csv
    db = case_db()
    records = []
    try:
        for key in dict.fromkeys(version_ids):
            row = db.execute('''SELECT v.*, c.site, c.dept, c.inspected FROM safety_case_versions v
                JOIN safety_cases c ON c.id=v.case_id WHERE v.id=? AND c.owner=?''',(key,str(owner))).fetchone()
            if not row:
                raise PermissionError('내 보고서만 반입 묶음으로 만들 수 있습니다.')
            result = dict(row)
            result['site'] = canonical_site_label(result.get('site', ''))
            records.append(result)
    finally:
        db.close()
    if not records:
        raise ValueError('보고서를 선택하세요.')
    out = io.BytesIO()
    listing = io.StringIO()
    writer = csv.writer(listing)
    writer.writerow(['점검번호','현장','점검일','구분','문서버전','생성일','파일명'])
    def safe(value):
        return re.sub(r'[\\/:*?"<>|\r\n]', '_', str(value))[:60]
    with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as bundle:
        for row in records:
            stem = f'{row["inspected"]}_{safe(row["site"])}_{row["case_id"]}_{row["kind"]}_v{row["revision"]}'
            bundle.writestr(stem+'.hwpx',row['hwpx'])
            bundle.writestr(stem+'.pdf',row['pdf'])
            # CSV를 스프레드시트로 열 때 수식 해석 방지.
            values = [row['case_id'],row['site'],row['inspected'],row['kind'],row['revision'],row['created'],stem]
            writer.writerow(["'"+str(v) if str(v).startswith(('=','+','-','@')) else v for v in values])
            if include_photos:
                for idx,item in json.loads(row['payload']).items():
                    for field,label in [('before_files','조치전'),('after_files','조치후')]:
                        for n,value in enumerate(item.get(field,[]),1):
                            raw = inspection_photo_bytes(value)
                            with Image.open(io.BytesIO(raw)) as photo:
                                ext = {'JPEG':'jpg','PNG':'png','WEBP':'webp'}.get(photo.format,'img')
                            bundle.writestr(f'{stem}_사진/항목{safe(idx)}_{label}_{n}.{ext}',raw)
        bundle.writestr('보고자료_목록.csv',listing.getvalue().encode('utf-8-sig'))
        bundle.writestr('반입안내.txt','승인된 망간 자료전송 절차로 반입하세요. PDF는 출력용, HWPX는 편집·전자결재용입니다. 동일 문서의 중복 등록에 주의하세요.'.encode('utf-8'))
    return out.getvalue()




def send_inspection_email(dept_name, site_name, inspector_id, form_data, report_bytes=None, report_name=None, pdf_bytes=None, delivery_key=None):
    """DB 기본키로 동시 클릭/재실행의 중복 발송을 막음. 결과 불명은 자동 재시도 금지."""
    import sqlite3
    key = delivery_key or (datetime.datetime.now(ZoneInfo("Asia/Seoul")).strftime("%Y-%m-%d") + ":" + inspection_report_key(dept_name, site_name, inspector_id, form_data))
    db = inspection_store()
    try:
        try:
            with db:
                db.execute("INSERT INTO deliveries VALUES (?, 'sending', '전송 진행 중')", (key,))
        except sqlite3.IntegrityError:
            status, detail = db.execute("SELECT status, detail FROM deliveries WHERE id=?", (key,)).fetchone()
            return status == "sent", f"중복 전송 차단 ({status}): {detail}"
        ok, detail = _send_inspection_email_once(dept_name, site_name, inspector_id, form_data, report_bytes, report_name, pdf_bytes)
        with db:
            if ok or detail.startswith("전송 결과 확인 필요"):
                db.execute("UPDATE deliveries SET status=?, detail=? WHERE id=?", ("sent" if ok else "unknown", detail, key))
            else:
                db.execute("DELETE FROM deliveries WHERE id=?", (key,))
        return ok, detail
    finally:
        db.close()


def _send_inspection_email_once(dept_name, site_name, inspector_id, form_data, report_bytes=None, report_name=None, pdf_bytes=None):
    from email import policy
    from email.parser import BytesParser
    from email.utils import formataddr, formatdate, make_msgid
    import zipfile

    smtp_started = False
    try:
        if not pdf_bytes or not pdf_bytes.startswith(b"%PDF-"):
            return False, "출력용 PDF가 없습니다. 보고서를 다시 생성해 주세요."
        if not isinstance(report_bytes, (bytes, bytearray)) or not report_bytes:
            return False, "첨부할 보고서가 없습니다. 한글 보고서를 다시 생성해 주세요."
        report_bytes = bytes(report_bytes)
        with zipfile.ZipFile(io.BytesIO(report_bytes)) as report_zip:
            if "Contents/section0.xml" not in report_zip.namelist() or report_zip.testzip():
                return False, "보고서 파일 검증에 실패했습니다. 보고서를 다시 생성해 주세요."

        smtp_conf = st.secrets.get("smtp", {})
        smtp_server = smtp_conf.get("server", "smtp.gmail.com")
        smtp_port = smtp_conf.get("port", 587)
        sender_email = smtp_conf.get("sender_email", "")
        sender_password = smtp_conf.get("sender_password", "")

        if not sender_email or not sender_password:
            return False, "이메일 설정(SMTP)이 누락되었습니다."

        user_emails_map = st.secrets.get("user_emails", {})
        receiver_email = user_emails_map.get(str(inspector_id), smtp_conf.get("receiver_email", sender_email))

        if not receiver_email:
            return False, f"해당 사번({inspector_id})에 매핑된 이메일 주소가 없습니다."

        msg = MIMEMultipart("mixed", policy=policy.SMTP)
        
        subject_str = f"[안전점검 보고] {dept_name} - {site_name} (작성자: {inspector_id})"
        msg['Subject'] = subject_str
        msg['From'] = formataddr(("KECO 안전점검시스템", sender_email), charset="utf-8")
        msg['To'] = receiver_email
        msg['Date'] = formatdate(localtime=True)
        msg['Message-ID'] = make_msgid()
        # 일부 웹메일의 한글 첨부명 처리 문제를 피하되 실제 파일 형식은 유지합니다.
        attachment_name = f"safety_inspection_{hashlib.sha256(report_bytes).hexdigest()[:12]}.hwpx"

        body_text = (
            "한국환경공단 현장 안전점검 결과 보고서를 송부합니다.\n\n"
            f"담당 부서: {dept_name}\n"
            f"점검 현장: {site_name}\n"
            f"작성자 사번: {inspector_id}\n"
            f"점검 항목: {len(form_data)}건\n\n"
            "조치 전·후 사진, 설명 및 AI 분석 내용은 첨부된 한글 보고서에서 확인해 주세요.\n\n"
            f"보고서명: {report_name or '안전점검_보고서.hwpx'}\n"
            f"첨부파일: {attachment_name}\n"
            f"첨부 크기: {len(report_bytes):,} bytes"
        )
        msg.attach(MIMEText(body_text, "plain", "utf-8"))
        report_part = MIMEApplication(report_bytes, _subtype="vnd.hancom.hwpx")
        report_part.set_param("name", attachment_name, header="Content-Type")
        report_part.add_header("Content-Disposition", "attachment",
                               filename=attachment_name)
        msg.attach(report_part)
        pdf_name = attachment_name.replace(".hwpx", ".pdf")
        pdf_part = MIMEApplication(pdf_bytes, _subtype="pdf")
        pdf_part.set_param("name", pdf_name, header="Content-Type")
        pdf_part.add_header("Content-Disposition", "attachment", filename=pdf_name)
        msg.attach(pdf_part)

        wire_message = msg.as_bytes(policy=policy.SMTP)
        parsed_message = BytesParser(policy=policy.default).parsebytes(wire_message)
        attachments = list(parsed_message.iter_attachments())
        if (len(attachments) != 2
                or attachments[0].get_filename() != attachment_name
                or attachments[0].get_payload(decode=True) != report_bytes
                or attachments[1].get_payload(decode=True) != pdf_bytes):
            return False, "메일 첨부 검증에 실패하여 전송을 중단했습니다."

        with smtplib.SMTP(smtp_server, smtp_port, timeout=30) as server:
            server.starttls()
            server.login(sender_email, sender_password)
            smtp_started = True
            refused = server.sendmail(sender_email, receiver_email, wire_message)
            if refused:
                return False, "메일 서버에서 수신자를 거부했습니다. 수신 주소를 확인해 주세요."

        return True, (f"메일 서버 접수 완료 · 첨부 2개: {attachment_name}, {pdf_name} "
                      f"({len(report_bytes):,} bytes) · 메시지 ID: {msg['Message-ID']}")
    except Exception as e:
        return False, ("전송 결과 확인 필요: 보낸메일 확인 후 관리자에게 문의하세요. " if smtp_started else "") + str(e)

def storage_csv_rows(raw):
    """Read legacy CSV bytes locally; never request Google credentials."""
    import csv
    raw = bytes(raw)
    if not raw or len(raw) > 10 * 1024 * 1024 or b'\x00' in raw:
        raise ValueError('CSV 파일(10MB 이하)을 선택해 주세요.')
    text = None
    for encoding in ('utf-8-sig', 'cp949'):
        try:
            text = raw.decode(encoding)
            break
        except UnicodeDecodeError:
            continue
    if text is None:
        raise ValueError('CSV 문자 인코딩을 확인해 주세요. UTF-8 또는 CP949를 지원합니다.')
    try:
        rows = []
        for row in csv.reader(io.StringIO(text, newline=''), strict=True):
            if not any(value.strip() for value in row):
                continue
            rows.append(row)
            if len(rows) > 20001:
                raise ValueError('한 번에 20,000개 이하의 기록을 가져와 주세요.')
        if not rows:
            raise ValueError('CSV에 가져올 기록이 없습니다.')
        return rows
    except csv.Error:
        raise ValueError('CSV 형식을 확인해 주세요. 쉼표·줄바꿈이 있는 내용은 따옴표로 감싸야 합니다.') from None


def inspection_history_actor(actor):
    actor = report_history_identity(actor)
    if st.secrets.get('user_roles', {}).get(actor) == 'contractor':
        raise PermissionError('외부 조치 계정은 내부 점검 현황을 이용할 수 없습니다.')
    return actor


def inspection_history_item_count(value):
    match = re.fullmatch(r'(\d+)\s*(?:(?:개|건)\s*(?:항목|세트)?)?', str(value).strip())
    return int(match.group(1)) if match and int(match.group(1)) <= 100000 else None


def inspection_history_record(rid, owner, dept, site, created, encoded):
    record = {'기록ID': str(rid), '날짜': str(created or ''), '점검 부서': str(dept or ''),
              '점검 현장': str(site or ''), '작성자': str(owner or ''), '항목수': '',
              'AI분석': '', '지적 분류': '', '사진경로': '', '자료 상태': ''}
    try:
        payload = json.loads(encoded)
        if not isinstance(payload, dict) or any(not isinstance(v, dict) for v in payload.values()):
            raise ValueError()
        analyses, details, photos = [], [], []
        for idx, item in payload.items():
            before, after = item.get('before_files', []), item.get('after_files', [])
            if not isinstance(before, list) or not isinstance(after, list):
                raise ValueError()
            analysis = str(item.get('ai_analysis', '')).strip()
            if analysis and analysis not in ('분석 미실행', '조치 전 AI 분석 미실행', '없음', 'nan'):
                analyses.append(f'[항목 #{idx}]:\n{analysis}')
            details.append(f"[항목 #{idx}] 조치 전: {item.get('desc_before', '') or '미기재'} / 조치 후: {item.get('desc_after', '') or '미기재'}")
            photos.append(f'[항목 #{idx}] 전:{len(before)}장, 후:{len(after)}장')
        record.update({'항목수': f'{len(payload)}개 항목',
                       'AI분석': '\n\n'.join(analyses) or '조치 전 AI 분석 미실행',
                       '지적 분류': '\n'.join(details), '사진경로': ' | '.join(photos)})
    except (ValueError, TypeError, KeyError):
        record['자료 상태'] = '점검 내용 형식 확인 필요'
        record['지적 분류'] = '저장된 점검 내용의 형식 확인이 필요합니다. 원본 백업을 확인해 주세요.'
    return record


def get_nhn_inspection_records(actor):
    """Aggregate saved metadata without fetching photos or document blobs."""
    inspection_history_actor(actor)
    db = inspection_store()
    try:
        return [inspection_history_record(*row) for row in report_history_inspection_rows(db)]
    finally:
        db.close()


