WX_PROVINCE_ALIASES = {
    '서울특별시': ('서울', '서울시'),
    '부산광역시': ('부산', '부산시'),
    '대구광역시': ('대구', '대구시'),
    '인천광역시': ('인천', '인천시'),
    '대전광역시': ('대전', '대전시'),
    '울산광역시': ('울산', '울산시'),
    '세종특별자치시': ('세종', '세종시'),
    '경기도': ('경기',),
    '강원특별자치도': ('강원', '강원도'),
    '충청북도': ('충북',),
    '충청남도': ('충남',),
    '전북특별자치도': ('전북', '전라북도'),
    '전남광주통합특별시': ('전남광주', '전남광주통합시'),
    '경상북도': ('경북',),
    '경상남도': ('경남',),
    '제주특별자치도': ('제주', '제주도'),
}


def wx_place_normalize(value):
    import unicodedata
    value = unicodedata.normalize('NFKC', str(value)).strip().replace('특례시', '시')
    return re.sub(r'[\s,·.\-]+', '', value).casefold()


def wx_place_aliases(region):
    province, local, _, _ = region
    prefixes = {province, *WX_PROVINCE_ALIASES.get(province, ())}
    # Older province names remain useful search terms; displayed names use the table.
    if province == '전남광주통합특별시' and local:
        prefixes.update(('광주', '광주시', '광주광역시') if local.endswith('구')
                        else ('전남', '전라남도'))
    if not local:
        return {wx_place_normalize(name) for name in prefixes}
    locals_ = {local, local[:-1] if local.endswith(('시', '군', '구')) else local}
    compact = wx_place_normalize(local)
    combined = re.fullmatch(r'(.+?시)(.+구)', compact)
    if combined:
        city, district = combined.groups()
        locals_.update((district, district[:-1], city[:-1]+district,
                        city+district[:-1], city[:-1]+district[:-1]))
    return {wx_place_normalize(name) for name in locals_} | {
        wx_place_normalize(prefix+name) for prefix in prefixes for name in locals_
    }


def wx_place_name(region):
    province, local, _, _ = region
    return province + (' ' + local if local else '')


def wx_search_places(query):
    """Match municipal names locally; never guess a grid from a geocoding result."""
    raw = str(query).strip()
    needle = wx_place_normalize(raw)
    if not needle:
        raise ValueError('시·군·구 지명을 입력해주세요. 예: 김포시, 서울 강남구')
    if len(needle) < 2 or len(raw) > 80:
        raise ValueError('시·군·구 지명을 두 글자 이상 입력해주세요.')
    indexed = [(region, wx_place_aliases(region)) for region in WX_REGIONS]
    exact = [region for region, aliases in indexed if needle in aliases]
    # "광주" must not silently select 경기도 광주시. The other urban districts
    # are offered using their current municipal names in the official table.
    if needle in ('광주', '광주광역시'):
        exact.extend(region for region in WX_REGIONS
                     if region[0] == '전남광주통합특별시' and region[1].endswith('구'))
    if exact:
        return sorted(set(exact), key=wx_place_name)
    # Exact matching first also permits short city names such as "구리".
    if re.search(r'[가-힣0-9]+(?:읍|면|동|리)(?=\s|$)', raw):
        raise ValueError('읍·면·동·리 대신 시·군·구까지만 입력해주세요. 예: 김포시')
    for province, aliases in WX_PROVINCE_ALIASES.items():
        if province.endswith('도') and needle in {wx_place_normalize(province), *(wx_place_normalize(a) for a in aliases)}:
            raise ValueError('시·도 이름에 시·군·구를 함께 입력해주세요. 예: 경기 김포시')
    matches = [region for region, aliases in indexed if any(needle in alias for alias in aliases)]
    return sorted(matches, key=wx_place_name)


def wx_direct_place(site_key):
    state_key = 'wx_place_state_' + site_key
    with st.form('wx_place_form_' + site_key):
        query = st.text_input('시·군·구 지명', placeholder='예: 김포시, 청주시, 서울 강남구',
                              max_chars=80, key='wx_place_query_' + site_key)
        confirmed = st.form_submit_button('확인', type='primary')
    if confirmed:
        # Every confirmation clears the previous area's data, including failures.
        for name in ('wx_scope', 'wx_result', 'wx_warnings'):
            st.session_state.pop(name, None)
        state = {'query': query.strip(), 'matches': []}
        try:
            state['matches'] = wx_search_places(query)
            if not state['matches']:
                state['error'] = '해당 시·군·구를 찾지 못했습니다. 지명이나 시·도를 확인해주세요. 예: 경기 광주시'
        except ValueError as exc:
            state['error'] = str(exc)
        st.session_state[state_key] = state
    state = st.session_state.get(state_key)
    if not state:
        st.caption('시·군·구 지명을 입력하고 확인을 눌러주세요.')
        return None
    if state.get('error'):
        st.warning(state['error'])
        return None
    matches = state['matches']
    if len(matches) == 1:
        region = matches[0]
    else:
        labels = {wx_place_name(region): region for region in matches}
        search_key = hashlib.sha256(state['query'].encode()).hexdigest()[:12]
        chosen = st.selectbox('조회할 시·군·구', list(labels), index=None,
                              placeholder='해당 지역을 선택하세요',
                              key='wx_place_match_' + site_key + '_' + search_key)
        if chosen is None:
            st.caption('검색된 지역이 여러 곳입니다. 시·군·구를 선택하면 날씨가 표시됩니다.')
            return None
        region = labels[chosen]
    resolved = (wx_place_name(region), region[2], region[3])
    load_now = confirmed or tuple(state.get('selected', ())) != resolved
    state['selected'] = resolved
    st.session_state[state_key] = state
    return (*resolved, load_now)


class WeatherAPIError(RuntimeError):
    def __init__(self, code, message):
        self.code = code
        super().__init__(message)


def wx_decode(raw):
    """JSON·XML 정상 응답과 오류를 구분. 응답 URL·인증키는 표시하지 않음."""
    try:
        response = json.loads(raw).get('response', {})
        header = response.get('header', {})
        code = str(header.get('resultCode', 'UNKNOWN'))
        body = response.get('body', {})
    except (ValueError, AttributeError, TypeError):
        try:
            if b'<!DOCTYPE' in raw.upper() or b'<!ENTITY' in raw.upper():raise ValueError()
            root = wx_et.fromstring(raw)
            code = root.findtext('.//returnReasonCode') or root.findtext('.//resultCode') or 'UNKNOWN'
            nodes = root.findall('.//items/item')
            values = [{child.tag: ''.join(child.itertext()) for child in node} for node in nodes]
            body = {'items': {'item': values}}
        except (ValueError, wx_et.ParseError):
            code = 'FORMAT'; body = {}
    if code in ('03', '3'):return []
    if code not in ('00', '0'):
        messages = {
            '30':'날씨 인증키를 확인해주세요.', '31':'인증키 사용 기간을 확인해주세요.',
            '32':'허용 IP 설정을 확인해주세요.', '20':'해당 날씨 서비스 활용신청·승인 상태를 확인해주세요.',
            '22':'오늘 API 요청 한도를 초과했습니다.', '10':'기상청 요청값 검증에 실패했습니다.',
            '12':'신청한 API 서비스가 제공되는지 확인해주세요.',
        }
        raise WeatherAPIError(code, '기상청 조회 실패: '+messages.get(code, '서비스 응답을 확인하고 잠시 후 다시 조회해주세요.')+' (코드 '+re.sub(r'[^A-Za-z0-9_]', '', code)[:16]+')')
    if not isinstance(body,dict):raise WeatherAPIError('FORMAT','기상청 자료 형식을 확인할 수 없습니다.')
    items = body.get('items', {}) or {}
    values = items.get('item', []) if isinstance(items, dict) else []
    if isinstance(values, dict):values = [values]
    if not isinstance(values,list) or any(not isinstance(value,dict) for value in values):
        raise WeatherAPIError('FORMAT','기상청 자료 형식을 확인할 수 없습니다.')
    return values


@st.cache_data(ttl=300, max_entries=256, show_spinner=False)
def wx_api(service, operation, key, params, cache_slot):
    allowed = {('VilageFcstInfoService_2.0','getUltraSrtNcst'),
               ('VilageFcstInfoService_2.0','getUltraSrtFcst'),
               ('WthrWrnInfoService','getWthrWrnList'),
               ('WthrWrnInfoService','getWthrWrnMsg'),
               ('WthrWrnInfoService','getPwnStatus')}
    if (service, operation) not in allowed:
        raise WeatherAPIError('CONFIG','날씨 요청 종류가 올바르지 않습니다.')
    # Encoding/Decoding 키 모두 1회 인코딩만 적용. '+' 문자는 보존합니다.
    normalized_key = wx_url.unquote(key.strip())
    query = wx_url.urlencode(dict(serviceKey=normalized_key, pageNo=1, numOfRows=1000,
                                 dataType='JSON', **params))
    endpoint = f'https://apis.data.go.kr/1360000/{service}/{operation}?{query}'
    try:
        req = wx_request.Request(endpoint, headers={'User-Agent':'KecoSafetyWeather/1.0'})
        with wx_request.urlopen(req, timeout=12) as reply:
            raw = reply.read(4_000_001)
        if len(raw) > 4_000_000:
            raise ValueError()
    except Exception:
        raise WeatherAPIError('NETWORK','기상청 연결에 실패했습니다. 인증키·승인 상태 또는 네트워크를 확인하고 다시 조회해주세요.') from None
    return wx_decode(raw)


def wx_base(now, forecast=False):
    # 매시 30분 예보는 발표 이후 여유 20분, 실황은 정시 이후 여유 40분을 둡니다.
    lag = 50 if forecast else 40
    base = now - datetime.timedelta(minutes=lag)
    return base.replace(minute=30 if forecast else 0, second=0, microsecond=0)


def wx_fetch_grid(key, nx, ny, now, forecast=False):
    base = wx_base(now, forecast)
    for back in range(2):
        candidate = base - datetime.timedelta(hours=back)
        params = {'base_date':candidate.strftime('%Y%m%d'), 'base_time':candidate.strftime('%H%M'),
                  'nx':nx, 'ny':ny}
        values = wx_api('VilageFcstInfoService_2.0', 'getUltraSrtFcst' if forecast else 'getUltraSrtNcst',
                        key, params, int(now.timestamp()//300))
        if values:
            # 다른 격자나 발표시각 자료를 잘못 표시하지 않습니다.
            values = [v for v in values if str(v.get('nx'))==str(nx) and str(v.get('ny'))==str(ny)
                      and str(v.get('baseDate'))==params['base_date'] and str(v.get('baseTime')).zfill(4)==params['base_time']]
            if values:
                return {'base':candidate.isoformat(), 'items':values}
    raise WeatherAPIError('NO_DATA','최근 발표 자료가 아직 없거나 제공이 지연되고 있습니다. 잠시 후 다시 조회해주세요.')


def wx_number(value):
    try:
        number = float(value)
        return number if -100 < number < 10000 else None
    except (ValueError, TypeError):
        return None


def wx_forecast_rows(items, now):
    groups = {}
    for item in items:
        try:
            when = datetime.datetime.strptime(str(item['fcstDate'])+str(item['fcstTime']).zfill(4),'%Y%m%d%H%M').replace(tzinfo=ZoneInfo('Asia/Seoul'))
        except (ValueError, KeyError):
            continue
        if when <= now:
            continue
        groups.setdefault(when, {})[item.get('category')] = item.get('fcstValue')
    sky = {'1':'맑음','3':'구름 많음','4':'흐림'}
    rain = {'1':'비','2':'비/눈','3':'눈','5':'빗방울','6':'빗방울/눈날림','7':'눈날림'}
    rows=[]
    for when, values in sorted(groups.items())[:6]:
        rows.append({'예보 시각':when.strftime('%m/%d %H:%M'),
                     '날씨':rain.get(str(values.get('PTY')), sky.get(str(values.get('SKY')),'확인 불가')),
                     '기온(℃)':wx_number(values.get('T1H')), '습도(%)':wx_number(values.get('REH')),
                     '풍속(m/s)':wx_number(values.get('WSD')), '1시간 강수량':str(values.get('RN1','미제공'))})
    return rows


