RA_IMPLEMENTATION_STATES = ['미착수', '저감조치 완료']


def ra_implementation_status(value):
    status = str(value or '').replace(' ', '')
    if status in ('저감조치완료', '완료·현장확인', '완료,현장확인'):
        return '저감조치 완료'
    return '미착수'


def ra_is_implemented(row):
    return ra_implementation_status(row.get('status')) == '저감조치 완료'


def ra_completed_score(row):
    return ra_score(row, True) if ra_is_implemented(row) else 0


def ra_iso_date(value):
    if isinstance(value, datetime.datetime):
        return value.date().isoformat()
    if isinstance(value, datetime.date):
        return value.isoformat()
    text = str(value or '').strip()
    match = re.fullmatch(r'(\d{4})\s*(?:[-./]|년)\s*(\d{1,2})\s*(?:[-./]|월)\s*(\d{1,2})\s*(?:일|\.)?', text)
    if not match:
        return ''
    try:
        return datetime.date(*(int(part) for part in match.groups())).isoformat()
    except ValueError:
        return ''


def ra_completion_date(row):
    return ra_iso_date(row.get('verified_date')) if ra_is_implemented(row) else ''


