def ra_render_measures(meta):
    st.markdown(RA_MEASURE_CANDIDATE_CSS, unsafe_allow_html=True)
    st.info('유해위험 제거·저감 → 공학적 대책 → 관리적 대책 → 개인보호구 순으로 검토하고, 담당자와 기한을 정합니다.')
    row = ra_active_row('measures')
    if not row: return
    st.write(f'**{ra_decision(row, meta)}**')
    examples = ra_examples_for(row['trade'], meta['construction_type'])
    with st.expander('1\\. 공단 감소대책을 활용한 작성', expanded=True):
        eid = st.selectbox('대책 참고 사례', [v['id'] for v in examples], format_func=lambda value: next(v['title'] for v in examples if v['id'] == value), key='ra_measures_example_'+row['id'])
        example = next(v for v in examples if v['id'] == eid)
        for kind, detail in example['controls']: st.write('• '+kind+' / '+detail)
        st.button('이 대책을 작성 초안에 추가', on_click=ra_fill_measures, args=(row['id'], eid), key='ra_measures_template_'+row['id'])
    with st.expander('2\\. 계획 예산, AI 대책을 활용한 작성'):
        band = ra_field('이 항목의 개선 예산', 'budget_note', row['id'], 'select', ['미정', '추가 비용 최소화', '50만원 이내', '100만원 이내', '500만원 이내', '직접 입력'])
        if band == '직접 입력': ra_field('계획 예산 상한 (원)', 'budget', row['id'], 'number', min_value=0, step=10000)
        else: row['budget'] = {'미정': 0, '추가 비용 최소화': 0, '50만원 이내': 500000, '100만원 이내': 1000000, '500만원 이내': 5000000}[band]
        st.caption('비용은 견적 확인 필요. 예산 부족 시 필수조치를 생략하지 않고 추가 예산·작업방법 변경을 검토합니다.')
        data = {k: row[k] for k in ('trade', 'work', 'category', 'hazards', 'factor', 'existing', 'frequency', 'severity', 'budget', 'budget_note', 'urgent')}
        data['construction_type'] = meta['construction_type']
        source = row['source']+'\n'+example['source']+'\n'+'\n'.join(text for _, text in example['controls'])
        sig = ra_hash([data, source])
        cache_key = 'ra_measures_ai_'+row['id']
        cache = st.session_state.get(cache_key, {})
        if st.button('AI 개선대책 후보 받기', key='ra_measure_ai_button_'+row['id']):
            try:
                with keco_loading('대책 후보를 작성하고 있습니다…', kind='steps', steps=('위험요인 확인', '감소대책 분석', '후보 정리')): cache = {'sig': sig, 'items': ra_ai('measures', data, source)}
                st.session_state[cache_key] = cache
            except Exception: st.error('AI 연결 확인 필요. 공단 예시와 직접 입력을 이용해 주세요.')
        options = cache.get('items', []) if cache.get('sig') == sig else []
        pick_key = 'ra_measure_picks_'+row['id']+'_'+sig[:10]
        picked = []
        st.markdown('**반영할 대책 후보**')
        with st.container(key='ra_measure_candidates'):
            for candidate in options:
                candidate_key = 'ra_measure_candidate_'+row['id']+'_'+ra_hash([sig, candidate])[:20]
                if st.checkbox(candidate, key=candidate_key):
                    picked.append(candidate)
        st.session_state[pick_key] = picked
        st.button('선택 대책을 작성 내용에 추가', disabled=not picked, on_click=ra_apply_ai_measures, args=(row['id'], pick_key), key='ra_measure_apply_'+row['id'])
        notice = st.session_state.pop('ra_measure_apply_notice_'+row['id'], None)
        if notice: st.success(notice)
        error = st.session_state.pop('ra_measure_apply_error_'+row['id'], None)
        if error: st.error(error)
    with st.container(key='ra_measures_final'):
        st.markdown('#### 3. 최종 감소대책 작성')
        ra_sync_control_headings(row)
        ra_field('감소대책 방법', 'control_types', row['id'], 'multi', RA_CONTROL_TYPES)
        ra_field('최종 감소대책', 'measures', row['id'], 'area', placeholder='선택한 대책방법 아래에 구체적인 개선내용과 작업 전 조건·검증방법을 작성하세요.')
        left, right = st.columns(2)
        with left: ra_field('개선 담당자', 'owner', row['id'])
        with right: ra_row_date_input(row, 'deadline', '개선 예정일·이행기한')
        ra_render_photo(row, 'before_photo', '조치 전 사진')


def ra_render_execution(meta):
    st.info('계획과 실제 이행을 구분해 기록하고, 개선 후 위험성을 직접 재평가합니다.')
    row = ra_active_row('execution')
    if not row: return
    st.write('**감소대책:** '+(row['measures'] or '④ 감소대책을 먼저 작성하세요.'))
    st.caption('개선 담당자 '+(row['owner'] or '미기재')+' / 예정일 '+(row['deadline'] or '미기재'))
    ra_field('이행 상태', 'status', row['id'], 'select', RA_IMPLEMENTATION_STATES)
    if not ra_is_implemented(row):
        return
    left, right = st.columns(2)
    with left: ra_field('완료 확인자', 'verified_by', row['id'])
    with right: ra_row_date_input(row, 'verified_date', '개선 완료일·확인일')
    ra_field('조치 결과 입력', 'evidence', row['id'], 'area', placeholder='사진·점검표의 보관 위치, 실제 개선 내용, 현장 확인 결과')
    ra_render_photo(row, 'after_photo', '조치 후 사진')
    ra_score_input(row, 'residual_f', '개선 후 빈도', 5)
    ra_score_input(row, 'residual_s', '개선 후 강도', 4)
    before, after = row['frequency']*row['severity'], row['residual_f']*row['residual_s']
    label = '저감조치 완료 후 재평가'
    st.write(f'**현재 {before or "미평가"} → 개선 후 {after or "미평가"} · {label}**')
    if after >= 8: st.warning('개선 후에도 8점 이상입니다. 감소대책을 다시 검토해 주세요.')
    st.caption('개선 후 점수와 개선 완료일은 최종 평가표의 해당란에 반영됩니다.')



def ra_report_sections(meta, rows, final):
    sections = [('사전준비 · 평가 개요', [
        ('평가방법',meta.get('method',RA_METHOD)),
        ('공사종류',meta.get('construction_type') or '확인 필요'),
        ('담당부서',meta.get('department','')),
        ('사업장명 / 주소',meta.get('site','')+' / '+meta.get('address','')),
        ('평가연도 / 평가일 / 구분',str(meta.get('assessment_year',''))+'년 / '+meta.get('date','')+' / '+meta.get('kind','')),
        ('수시평가 사유',meta.get('trigger','') or '해당 없음 또는 미기재'),
        ('작성자(공단 안전관리자)',meta.get('evaluator','')),
        ('평가 대상 작업 개요',meta.get('work_scope','')),
        ('평가 대상 공종', '\n'.join(meta.get('trades',[]))),
        ('평가기준',RA_PROCEDURE+' · 빈도 5단계 × 강도 4단계'),
        ('결재 방법','보고서 출력 후 지면 결재. 시스템의 보고서 생성·저장 상태는 결재 완료를 의미하지 않습니다.')])]
    for number, row in enumerate(rows, 1):
        before, after = row['frequency']*row['severity'], row['residual_f']*row['residual_s']
        sections.append((f'평가 항목 {number} · '+row['trade'], [
            ('세부작업·위치·조건', row['work']), ('위험분류 / 유형', row.get('category', '')+' / '+' · '.join(row['hazards'])),
            ('유해·위험발생상황', row['factor']), ('확인 방법 / 출처', row.get('origin', '')+' / '+row['source_note']),
            ('현재 안전보건조치', row['existing']),
            ('현재 위험성', f'빈도 {row["frequency"] or "미평가"} × 강도 {row["severity"] or "미평가"} = {before or "미평가"} / '+ra_risk_level(before)[0]),
            ('점수 판단 사유', row['reason']), ('조치 판단', ra_decision(row, meta)),
            ('급박한 위험 표시', '급박한 위험 우려' if row['urgent'] else '별도 표시 없음'),
            ('위험성 감소대책', row['measures']), ('감소대책 방법', ' / '.join(row.get('control_types', []))),
            ('계획 예산', f'{row["budget"]:,}원 / {row["budget_note"]} / 견적 확인 필요'),
            ('개선 담당자 / 예정일', row['owner']+' / '+row['deadline']), ('이행 상태', ra_implementation_status(row.get('status'))),
            ('개선 후 위험성', f'빈도 {row["residual_f"] or "미평가"} × 강도 {row["residual_s"] or "미평가"} = {ra_completed_score(row) or "미평가"}' if ra_is_implemented(row) else '미착수'),
            ('완료 확인자 / 확인일', row['verified_by']+' / '+ra_completion_date(row) if ra_is_implemented(row) else ''),
            ('이행 증빙·현장 점검', row['evidence'] if ra_is_implemented(row) else ''),
            ('잔여 위험·추가 개선', (row.get('followup', '') or ('8점 이상 · 추가 개선 확인 필요' if after >= 8 else '현장 확인 필요')) if ra_is_implemented(row) else ''),
            ('참고자료', row['source'] or '직접 입력 또는 일반적인 검토 후보')]))
    sections.append(('현장 전달·후속 점검 기록',[
        ('전달 상태 / 일자 / 방법',meta.get('sharing_state','')+' / '+meta.get('sharing_date','')+' / '+meta.get('sharing_method','')),
        ('공단 작성자의 현장 전달 기록',meta.get('sharing','') or '선택 기록 · 미기재'),
        ('후속 점검 계획',meta.get('followup','') or '선택 기록 · 미기재'),
        ('보완사항 / 완료 예정일',meta.get('supplement','')+' / '+meta.get('supplement_deadline','')),
        ('문서 관리','출력한 결재 문서와 현장 확인자료는 기관·현장의 보존기준에 따라 관리합니다.'),
        ('작성 자료',RA_PROCEDURE),
        ('작성 범위','공단 안전관리자가 현장 자료를 바탕으로 정리한 작성 지원 보고서입니다. 결재는 지면으로 진행합니다.')]))
    return sections



def ra_evaluation_grid(rows):
    headers = ['번호', '공정·작업', '위험분류', '위험발생상황', '현재 안전조치', '빈도', '강도', '위험성',
               '위험성 감소대책', '대책방법', '개선 후 위험성', '개선 예정일', '개선 완료일', '담당자']
    values = [[str(i), row['trade'], row.get('category', ''), row['factor'], row['existing'],
               str(row['frequency'] or '-'), str(row['severity'] or '-'), str(row['frequency']*row['severity'] or '-'),
               row['measures'], ' / '.join(row.get('control_types', [])),
               str(ra_completed_score(row) or '-'),
               ra_iso_date(row.get('deadline')), ra_completion_date(row) or '-', row['owner']] for i, row in enumerate(rows, 1)]
    return headers, values


RA_FORM16_VERSION = 'keco-form16-20261104-v2'


def ra_photo_encode(raw):
    from PIL import ImageOps
    raw = bytes(raw)
    if not raw or len(raw) > 20*1024*1024:
        raise ValueError('사진은 20MB 이하의 파일을 선택해 주세요.')
    try:
        with Image.open(io.BytesIO(raw)) as opened:
            if opened.width*opened.height > 40000000:
                raise ValueError('사진 해상도가 큽니다. 크기를 줄여 다시 등록해 주세요.')
            picture = ImageOps.exif_transpose(opened)
            if 'A' in picture.getbands():
                background = Image.new('RGB', picture.size, 'white')
                background.paste(picture, mask=picture.getchannel('A'))
                picture = background
            else:
                picture = picture.convert('RGB')
            picture.thumbnail((1400,1400), Image.Resampling.LANCZOS)
            for quality in (82,72,62):
                output = io.BytesIO()
                picture.save(output, format='JPEG', quality=quality, optimize=True)
                if output.tell() <= 350*1024:
                    break
            if output.tell() > 350*1024:
                picture.thumbnail((1000,1000), Image.Resampling.LANCZOS)
                output = io.BytesIO()
                picture.save(output, format='JPEG', quality=65, optimize=True)
            return base64.b64encode(output.getvalue()).decode('ascii')
    except (OSError, Image.DecompressionBombError) as exc:
        raise ValueError('사진 파일을 읽지 못했습니다. JPG·PNG·WEBP 파일을 다시 선택해 주세요.') from exc


def ra_photo_info(value):
    if not value:
        return None
    try:
        encoded = str(value).split(',',1)[-1] if str(value).startswith('data:image/') else str(value)
        raw = base64.b64decode(encoded, validate=True)
        with Image.open(io.BytesIO(raw)) as picture:
            width,height = picture.size
            format_name = picture.format
            orientation = picture.getexif().get(274,1)
            picture.verify()
        if format_name not in ('JPEG','PNG') or orientation != 1:
            return ra_photo_info(ra_photo_encode(raw))
        return dict(data=raw,width=width,height=height,format='jpg' if format_name=='JPEG' else 'png')
    except (ValueError, OSError, Image.DecompressionBombError) as exc:
        raise ValueError('등록한 사진의 형식 확인이 필요합니다. 해당 사진을 다시 등록해 주세요.') from exc


def ra_photo_changed(row_id, field, upload_key, state_key):
    if not _perf_actor_allowed(st.session_state.get('ra_actor')):
        return
    try:
        upload = st.session_state.get(upload_key)
        encoded = ra_photo_encode(upload.getvalue()) if upload is not None else ''
        ra_set_field(row_id, field, encoded)
        st.session_state.pop(state_key+'_error',None)
    except (ValueError, OSError) as exc:
        st.session_state[state_key+'_error'] = str(exc)
        st.session_state[state_key+'_generation'] = st.session_state.get(state_key+'_generation',0)+1


def ra_photo_remove(row_id, field, state_key):
    if not _perf_actor_allowed(st.session_state.get('ra_actor')):
        return
    ra_set_field(row_id,field,'')
    st.session_state[state_key+'_generation'] = st.session_state.get(state_key+'_generation',0)+1
    st.session_state.pop(state_key+'_error',None)


def ra_render_photo(row, field, label):
    state_key = 'ra_photo_'+row['id']+'_'+field
    generation = st.session_state.get(state_key+'_generation',0)
    upload_key = state_key+'_upload_'+str(generation)
    st.file_uploader(label+' (선택)',type=['jpg','jpeg','png','webp'],key=upload_key,
                     on_change=ra_photo_changed,args=(row['id'],field,upload_key,state_key))
    error = st.session_state.pop(state_key+'_error',None)
    if error: st.error(error)
    if row.get(field):
        st.caption(label+'이 연결되어 있습니다. 사진도 임시저장·최종저장에 함께 보관됩니다.')
        with st.expander(label+' 보기·삭제'):
            try:
                photo = ra_photo_info(row[field])
                st.image(photo['data'],width=320)
            except ValueError as exc:
                st.warning(str(exc))
            st.button(label+' 삭제',key=state_key+'_remove',on_click=ra_photo_remove,args=(row['id'],field,state_key))


def ra_form16_layout(meta, rows, final):
    from reportlab.lib.pagesizes import A4, landscape
    width,height = landscape(A4)
    margin,gap = 24.0,14.0
    table_width = width-2*margin
    panel_width = (table_width-gap)/2
    columns = [panel_width*v/390 for v in (45,70,80,45,70,80)]
    body_height = height-2*margin-16-38
    font_size,leading = 7.3,9.6
    segments = []
    for number,row in enumerate(rows,1):
        info = [str(number)+'. '+ra_form14_text(row.get('trade')), ra_form14_text(meta.get('department')),
                ra_form14_text(meta.get('execution_supervisor')),
                '(점검담당) '+ra_form14_text(meta.get('evaluator'))+'\n(개선담당) '+ra_form14_text(row.get('owner'))]
        info_lines = [ra_form14_wrap(value,columns[1]+columns[2]-8,font_size) for value in info]
        overflow = []
        for index,value in enumerate(info_lines):
            if len(value)>4:
                overflow += [['공정분류','부명','관리감독자','담당자'][index]+'(계속)']+value[3:]
                info_lines[index] = value[:3]+['계속: 유해위험요인란']
        factor = '\n'.join(overflow+[ra_form14_text(row.get('factor'))])
        factors = ra_form14_wrap(factor,columns[1]+columns[2]-8,font_size)
        measures = ra_form14_wrap(ra_form14_text(row.get('measures')),columns[4]+columns[5]-8,font_size)
        try:
            before = ra_photo_info(row.get('before_photo'))
            after = ra_photo_info(row.get('after_photo')) if ra_is_implemented(row) else None
        except ValueError as exc:
            raise ValueError(f'{number}번 평가 항목: '+str(exc)) from exc
        count = max(1,(max(len(factors),len(measures))+11)//12)
        for part in range(count):
            segments.append(dict(number=number,continued=part>0,info=info_lines,
                factor=factors[part*12:(part+1)*12] or [''],measures=measures[part*12:(part+1)*12] or [''],
                before=before if part==0 else None,after=after if part==0 else None,row=row))
    pages = []
    for index in range(0,len(segments),2):
        pair = segments[index:index+2]
        info1 = max(25,max(max(len(panel['info'][0]),len(panel['info'][1])) for panel in pair)*leading+8)
        info2 = max(29,max(max(len(panel['info'][2]),len(panel['info'][3])) for panel in pair)*leading+8)
        description = max(62,max(max(len(panel['factor']),len(panel['measures'])) for panel in pair)*leading+8)
        heights = [info1,info2,30,18,description,0,22,27,24,28]
        heights[5] = body_height-sum(heights)
        if heights[5]<110:
            raise ValueError('이행결과 보고서의 표시 분량 확인 필요')
        panels = []
        for panel in pair:
            row = panel['row']
            cells = []
            def add(r,c,span,text,size=font_size,align='left',gray=False,photo=None):
                lines = list(text) if isinstance(text,list) else str(text).split('\n')
                cells.append(dict(r=r,c=c,span=span,lines=lines,size=size,align=align,gray=gray,photo=photo))
            add(0,0,1,'공정분류',align='center',gray=True);add(0,1,2,panel['info'][0])
            add(0,3,1,'부  명',align='center',gray=True);add(0,4,2,panel['info'][1])
            add(1,0,1,'관리감독자',align='center',gray=True);add(1,1,2,panel['info'][2])
            add(1,3,1,'담당자',align='center',gray=True);add(1,4,2,panel['info'][3])
            title = '위험성 감소대책 수립 및 이행결과'
            add(2,0,6,title,size=14,align='center',gray=True)
            add(3,0,3,'개선 전',align='center',gray=True);add(3,3,3,'개선 후',align='center',gray=True)
            add(4,0,1,'유해위험\n요인',align='center',gray=True);add(4,1,2,panel['factor'])
            add(4,3,1,'감소\n대책',align='center',gray=True);add(4,4,2,panel['measures'])
            continued = '같은 평가 항목의 사진은 앞쪽 참조' if panel['continued'] else ''
            add(5,0,3,continued or '조치 전 사진 미등록',align='center',photo=panel['before'])
            add(5,3,3,continued or ('조치 후 사진 미등록' if ra_is_implemented(row) else '저감조치 완료 후 등록'),align='center',photo=panel['after'])
            add(6,0,3,'현재 위험성',align='center',gray=True);add(6,3,3,'개선 후 위험성',align='center',gray=True)
            for c,label in enumerate(['가능성\n(빈도)','중대성\n(강도)','위험성']*2):
                add(7,c,1,label,align='center')
            scores = [row.get('frequency') or '',row.get('severity') or '',ra_score(row) or '',
                      row.get('residual_f') or '' if ra_is_implemented(row) else '',
                      row.get('residual_s') or '' if ra_is_implemented(row) else '',ra_completed_score(row) or '']
            for c,value in enumerate(scores):add(8,c,1,value,align='center')
            add(9,0,3,'완료여부'+(' · 계속' if panel['continued'] else ''),align='center',gray=True)
            add(9,3,3,ra_implementation_status(row.get('status')),align='center',gray=True)
            panels.append(dict(cells=cells,number=panel['number'],continued=panel['continued']))
        pages.append(dict(panels=panels,heights=heights))
    meta_line = ' / '.join(ra_form14_text(meta.get(key)) for key in ('site','date','kind') if meta.get(key))
    return dict(width=width,height=height,margin=margin,gap=gap,table_width=table_width,
                panel_width=panel_width,columns=columns,pages=pages,meta_line=meta_line,leading=leading)


def ra_form16_draw_pdf(pdf, model, start_page=0, total_pages=None):
    from reportlab.lib.utils import ImageReader
    font = ra_form14_font()
    total_pages = total_pages or start_page+len(model['pages'])
    def cell(x,top,width,height,item):
        pdf.saveState();pdf.setLineWidth(.45);pdf.setStrokeColorRGB(0,0,0)
        if item['gray']:
            pdf.setFillColorRGB(.945,.945,.945);pdf.rect(x,top-height,width,height,fill=1,stroke=0)
        pdf.rect(x,top-height,width,height,fill=0,stroke=1)
        photo = item.get('photo')
        if photo:
            scale = min((width-12)/photo['width'],(height-12)/photo['height'])
            photo_width,photo_height = photo['width']*scale,photo['height']*scale
            pdf.drawImage(ImageReader(io.BytesIO(photo['data'])),x+(width-photo_width)/2,
                          top-height+(height-photo_height)/2,width=photo_width,height=photo_height,mask='auto')
        else:
            lines,size = item['lines'],item['size']
            leading = model['leading'] if size<10 else size*1.2
            centered = item['align']=='center'
            baseline = top-(max(4,(height-len(lines)*leading)/2) if centered else 4)-size
            pdf.setFillColorRGB(0,0,0)
            for line in lines:
                text_width = pdfmetrics.stringWidth(line,font,size)
                left = x+(width-text_width)/2 if centered else x+4
                text=pdf.beginText(left,baseline);text.setFont(font,size)
                if item['r']==2:text.setTextRenderMode(2);pdf.setLineWidth(.15)
                text.textOut(line);pdf.drawText(text);baseline-=leading
        pdf.restoreState()
    for page_number,page in enumerate(model['pages'],start_page+1):
        margin = model['margin'];top=model['height']-margin
        meta_lines = ra_form14_wrap(model['meta_line'],model['table_width']-95,6.8)
        for offset,line in enumerate(meta_lines[:2]):
            pdf.setFont(font,6.8);pdf.drawRightString(model['width']-margin,top-8-offset*7.5,line)
        top-=16
        for side,panel in enumerate(page['panels']):
            left = margin+side*(model['panel_width']+model['gap'])
            for item in panel['cells']:
                x=left+sum(model['columns'][:item['c']]);y=top-sum(page['heights'][:item['r']])
                width=sum(model['columns'][item['c']:item['c']+item['span']])
                cell(x,y,width,page['heights'][item['r']],item)
        pdf.setFont(font,8.5);pdf.drawString(margin,36,'붙임 KECO-P-610-12')
        pdf.drawCentredString(model['width']/2,36,'한국환경공단')
        pdf.drawRightString(model['width']-margin,36,'A4(210mm×297mm)')
        pdf.setFont(font,7);pdf.drawCentredString(model['width']/2,20,f'{page_number} / {total_pages}')
        pdf.showPage()


def ra_form16_append_hwpx(doc, model, start_page=0, total_pages=None):
    hp='http://www.hancom.co.kr/hwpml/2011/paragraph'
    total_pages=total_pages or start_page+len(model['pages'])
    styles=doc.styles if hasattr(doc,'styles') else doc
    apply_format=styles.apply_paragraph_format if hasattr(styles,'apply_paragraph_format') else doc.set_paragraph_format
    make_fill=styles.ensure_border_fill if hasattr(styles,'ensure_border_fill') else doc.ensure_border_fill
    plain=make_fill(border_color='#000000',border_width='0.12 mm')
    gray=make_fill(border_color='#000000',border_width='0.12 mm',fill_color='#F1F1F1')
    empty=make_fill(border_color='#FFFFFF',border_width='0.12 mm',active_borders=[])
    formats={}
    for key,align,percent in [('LEFT','LEFT',130),('CENTER','CENTER',130),('RIGHT','RIGHT',130),('PICTURE','CENTER',100)]:
        p=doc.add_paragraph('',para_pr_id_ref='0')
        apply_format(paragraphs=[p],alignment=align,line_spacing_percent=percent,
                     spacing_before_pt=0,spacing_after_pt=0,indent_left_mm=0,indent_right_mm=0,first_line_indent_mm=0)
        formats[key]=p.element.get('paraPrIDRef');p.remove()
    def put(cell,lines,size=7.3,align='LEFT',fill=None,bold=False):
        cell.set_text('');cell.element.set('borderFillIDRef',str(plain if fill is None else fill))
        cell.element.set('hasMargin','1')
        margins=cell.element.find('{%s}cellMargin'%hp)
        if margins is not None:
            for side in ('left','right','top','bottom'):margins.set(side,'400')
        sublist=cell.element.find('{%s}subList'%hp)
        sublist.set('vertAlign','CENTER' if align!='LEFT' else 'TOP');sublist.set('lineWrap','SQUEEZE')
        for index,line in enumerate(lines):
            p=cell.paragraphs[0] if index==0 else cell.add_paragraph('')
            p.element.set('paraPrIDRef',formats[align]);p.element.set('styleIDRef','0')
            for run in list(p.runs):p.element.remove(run.element)
            p.add_run(str(line),font='맑은 고딕',size=size,bold=bold)
    def table(widths,heights,new_page=False,border=None):
        widths=[round(value*100) for value in widths];heights=[round(value*100) for value in heights]
        obj=doc.add_table(rows=len(heights),cols=len(widths),width=sum(widths),height=sum(heights),
                          border_fill_id_ref=plain if border is None else border,para_pr_id_ref=formats['LEFT'])
        obj.element.set('pageBreak','NONE');obj.element.set('repeatHeader','0')
        if new_page:apply_format(paragraphs=[obj.paragraph],page_break_before=True)
        for r,height in enumerate(heights):
            for c,width in enumerate(widths):obj.cell(r,c).set_size(width=width,height=height)
        return obj
    for page_number,page in enumerate(model['pages'],start_page+1):
        header=table([90,model['table_width']-90],[16],new_page=True,border=empty)
        put(header.cell(0,0),[''],size=9,fill=empty)
        put(header.cell(0,1),ra_form14_wrap(model['meta_line'],model['table_width']-98,6.8),size=6.8,align='RIGHT',fill=empty)
        widths=model['columns']+[model['gap']]+model['columns']
        grid=table(widths,page['heights'])
        grid.merge_cells(0,6,9,6);put(grid.cell(0,6),[''],fill=empty)
        for side in range(2):
            start=side*7
            if side>=len(page['panels']):
                grid.merge_cells(0,start,9,start+5);put(grid.cell(0,start),[''],fill=empty)
                continue
            for item in page['panels'][side]['cells']:
                r,c,span=item['r'],start+item['c'],item['span']
                if span>1:grid.merge_cells(r,c,r,c+span-1)
                target=grid.cell(r,c)
                put(target,item['lines'],size=item['size'],align='CENTER' if item['align']=='center' else 'LEFT',fill=gray if item['gray'] else plain,bold=item['r']==2)
                photo=item.get('photo')
                if photo:
                    width=sum(model['columns'][item['c']:item['c']+span])-14
                    height=page['heights'][r]-22
                    scale=min(width/photo['width'],height/photo['height'])
                    obj=doc.add_picture(photo['data'],photo['format'],width_mm=photo['width']*scale*25.4/72,
                                        height_mm=photo['height']*scale*25.4/72,align='CENTER',para_pr_id_ref=formats['PICTURE'])
                    picture_p=obj.element
                    while picture_p.tag!='{%s}p'%hp:picture_p=picture_p.getparent()
                    sublist=target.element.find('{%s}subList'%hp)
                    for child in list(sublist):sublist.remove(child)
                    sublist.set('vertAlign','CENTER');sublist.append(picture_p)
        footer=table([model['table_width']/3]*3,[27],border=empty)
        for col,label in enumerate(['붙임 KECO-P-610-12',f'한국환경공단\n{page_number} / {total_pages}','A4(210mm×297mm)']):
            put(footer.cell(0,col),label.split('\n'),size=8,align=['LEFT','CENTER','RIGHT'][col],fill=empty)


RA_FORM14_VERSION = 'keco-risk-report-20261104-form14-form16-v2'


def ra_form14_text(value):
    text = '' if value is None else str(value)
    text = text.replace('\r\n', '\n').replace('\r', '\n').replace('\t', ' ')
    return re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f\U00010000-\U0010ffff\u2600-\u27bf\ufe0f]', '', text)


def ra_form14_font():
    if 'KecoNanum' not in pdfmetrics.getRegisteredFontNames():
        generate_inspection_pdf('', '', '', {})
    return 'KecoNanum'


def ra_form14_wrap(value, width, size):
    """Wrap without truncation, using the embedded Korean font's actual widths."""
    font = ra_form14_font()
    text = str(value or '')
    result = []
    for line in text.split('\n'):
        current = ''
        for char in line:
            if current and pdfmetrics.stringWidth(current+char, font, size) > width:
                split=current.rfind(' ')
                if split > len(current)*.45:
                    result.append(current[:split])
                    current=current[split+1:]
                else:
                    result.append(current)
                    current = ''
            current += char
        result.append(current)
    return result or ['']


def ra_form14_layout(meta, rows, final):
    """One shared, measured page model for the PDF and editable HWPX forms."""
    from reportlab.lib.pagesizes import A4, landscape
    width, height = landscape(A4)
    margin = 24.0
    table_width = width-2*margin
    ratios = [38,155,187,197,61,63,67,136,171,60,82,82,55]
    columns = [table_width*value/sum(ratios) for value in ratios]
    sizes = [7.4,7.5,7.5,7.5,7.5,7.5,7.5,6.7,7.5,7.0,6.8,6.8,7.2]
    leading = [10.0,10.3,10.3,10.3,10.0,10.0,10.0,9.2,10.3,9.5,9.0,9.0,10.0]
    info_widths = [table_width*v for v in [.075,.14,.075,.275,.055,.14,.07,.17]]
    minimum = 62.0
    def blank_row():
        cells=[[''] for _ in range(13)]
        labels='\n'.join(f'{i}. {label} □' for i,label in enumerate(RA_CONTROL_TYPES,1))
        cells[7]=ra_form14_wrap(labels,columns[7]-8,sizes[7])
        return dict(cells=cells,height=minimum,number=None,continued=False)
    groups = []
    for number, row in enumerate(rows, 1):
        key = (ra_form14_text(row.get('trade')), ra_form14_text(row.get('work')))
        if not groups or groups[-1]['key'] != key:
            groups.append(dict(key=key, items=[]))
        groups[-1]['items'].append((number, row))
    if not groups:
        groups.append(dict(key=('', ''), items=[]))
    pages = []
    for group in groups:
        trade, work = group['key']
        major, separator, subtask = trade.partition(' / ')
        process = major if separator else (trade or ra_form14_text(meta.get('construction_type')))
        work_text = '\n'.join(v for v in ([subtask] if separator else [])+[work or ra_form14_text(meta.get('work_scope'))] if v)
        info = ['공정분류', process, '작업내용', work_text, '부  명', ra_form14_text(meta.get('department')), '담당자', ra_form14_text(meta.get('evaluator'))]
        info_lines = [ra_form14_wrap(value, info_widths[i]-8, 8.0) for i,value in enumerate(info)]
        overflow = []
        # Exceptionally long context is continued in the first situation cell.
        # Keep a readable, bounded header and retain every character in the form.
        if len(info_lines[3]) > 7:
            overflow = info_lines[3][6:]
            info_lines[3] = info_lines[3][:6]+['작업내용 계속: 아래 위험발생상황란']
        for index in (1,5,7):
            if len(info_lines[index]) > 7:
                overflow += [info[index-1]+'(계속)']+info_lines[index][6:]
                info_lines[index] = info_lines[index][:6]+['계속: 아래 참조']
        info_height = max(32.0, max(len(v) for v in info_lines)*10.5+8)
        # Reserve room for table-object baselines in Hancom as well as footers.
        body_height = height-2*margin-16-30-info_height-54-22-14
        capacity = body_height
        segments = []
        for item_index,(number,row) in enumerate(group['items']):
            score = ra_score(row)
            residual = ra_completed_score(row)
            after = str(residual) if residual else ''
            types = {ra_canonical_control(value) for value in row.get('control_types', [])}
            controls = '\n'.join(f'{i}. {label} '+('■' if label in types else '□') for i,label in enumerate(RA_CONTROL_TYPES,1))
            situation = ra_form14_text(row.get('factor'))
            if item_index == 0 and overflow:
                situation = '\n'.join(overflow)+'\n위험발생상황\n'+situation
            deadline=ra_iso_date(row.get('deadline'))
            completed=ra_completion_date(row)
            values = [str(number),ra_form14_text(row.get('category')),situation,
                      ra_form14_text(row.get('existing')),str(row.get('frequency') or ''),str(row.get('severity') or ''),
                      str(score or ''),controls,ra_form14_text(row.get('measures')),after,
                      deadline,completed,
                      ra_form14_text(row.get('owner'))]
            wrapped = [ra_form14_wrap(value, columns[i]-8, sizes[i]) for i,value in enumerate(values)]
            persistent = {0,4,5,6,7,9}
            remaining = {i:list(v) for i,v in enumerate(wrapped) if i not in persistent}
            continued = False
            while True:
                cells = []
                for col in range(13):
                    if col in persistent:
                        cells.append(list(wrapped[col]))
                    else:
                        count = max(1, int((capacity-10)/leading[col]))
                        cells.append(remaining[col][:count] or [''])
                        remaining[col] = remaining[col][count:]
                if continued: cells[0] = [str(number)]+ra_form14_wrap('계속',columns[0]-8,sizes[0])
                needed = max(minimum, max(len(v)*leading[i]+10 for i,v in enumerate(cells)))
                segments.append(dict(cells=cells, height=min(capacity,needed), number=number, continued=continued))
                if not any(remaining.values()): break
                continued = True
        if not segments:
            segments.append(blank_row())
        current = []
        used = 0
        for segment in segments:
            if current and (len(current) >= 5 or used+segment['height'] > body_height+.01):
                pages.append(dict(info=info_lines,info_height=info_height,rows=current,body_height=body_height))
                current=[];used=0
            current.append(segment);used += segment['height']
        if current:
            pages.append(dict(info=info_lines,info_height=info_height,rows=current,body_height=body_height))
    for page in pages:
        body = page['rows']
        while len(body) < 5 and sum(row['height'] for row in body)+minimum <= page['body_height']+.01:
            body.append(blank_row())
        spare = max(0,page['body_height']-sum(row['height'] for row in body))/len(body)
        for row in body: row['height'] += spare
    site = ra_form14_text(meta.get('site'))
    meta_line = ' / '.join(v for v in [site,ra_form14_text(meta.get('date')),ra_form14_text(meta.get('kind')),'' if final else '초안'] if v)
    return dict(width=width,height=height,margin=margin,table_width=table_width,columns=columns,
                sizes=sizes,leading=leading,info_widths=info_widths,pages=pages,meta_line=meta_line)



def ra_pdf(meta, rows, final, include_execution=True):
    from reportlab.pdfgen import canvas
    model = ra_form14_layout(meta, rows, final)
    execution = ra_form16_layout(meta, rows, final) if include_execution else None
    total_pages = len(model["pages"])+(len(execution["pages"]) if execution else 0)
    output = io.BytesIO()
    pdf = canvas.Canvas(output,pagesize=(model['width'],model['height']))
    pdf.setTitle('위험성평가 및 감소대책 수립·이행결과' if include_execution else '위험성평가(위험성 결정)')
    font = ra_form14_font()
    margin, table_width = model['margin'], model['table_width']
    def cell(x,top,width,height,lines,*,size=8,leading=10.5,align='left',bold=False,gray=False,border=True,center=False):
        pdf.saveState()
        pdf.setLineWidth(.45)
        if gray:
            pdf.setFillColorRGB(.945,.945,.945)
            pdf.rect(x,top-height,width,height,fill=1,stroke=0)
        pdf.setFillColorRGB(0,0,0);pdf.setStrokeColorRGB(0,0,0)
        if border:pdf.rect(x,top-height,width,height,fill=0,stroke=1)
        offset = max(4,(height-len(lines)*leading)/2) if center else 4
        baseline = top-offset-size
        for line in lines:
            text_width = pdfmetrics.stringWidth(line,font,size)
            left = x+(width-text_width)/2 if align=='center' else x+width-4-text_width if align=='right' else x+4
            text=pdf.beginText(left,baseline);text.setFont(font,size)
            if bold:text.setTextRenderMode(2);pdf.setLineWidth(.15)
            text.textOut(line);pdf.drawText(text);baseline -= leading
        pdf.restoreState()
    for page_number,page in enumerate(model['pages'],1):
        top = model['height']-margin
        meta_size=7.1
        meta_lines = ra_form14_wrap(model['meta_line'],table_width-92,meta_size)
        # A long site name stays readable in two lines in the same metadata band.
        if len(meta_lines)>2:
            meta_size=6.0
            meta_lines = ra_form14_wrap(model['meta_line'],table_width-92,meta_size)
        cell(margin+88,top,table_width-88,16,meta_lines,size=meta_size,leading=7.8,align='right',border=False)
        top -= 16
        cell(margin,top,table_width,30,['위험성평가(위험성 결정)'],size=16,leading=19,align='center',bold=True,gray=True,center=True)
        top -= 30
        x=margin
        for i,(width,lines) in enumerate(zip(model['info_widths'],page['info'])):
            cell(x,top,width,page['info_height'],lines,size=8,align='center' if i%2==0 else 'left',bold=i%2==0,gray=i%2==0,center=True)
            x += width
        top -= page['info_height']
        xs=[margin]
        for width in model['columns']:xs.append(xs[-1]+width)
        # Two-level merged headers follow the supplied form's thirteen columns.
        for col in (0,3,9,10,11,12):
            label={0:'번\n호',3:'현재의\n안전보건조치',9:'개선후\n위험성',10:'개선\n예정일',11:'개선\n완료일',12:'담당자'}[col]
            cell(xs[col],top,model['columns'][col],54,label.split('\n'),size=7.5,align='center',bold=True,gray=True,center=True)
        for start,end,label in [(1,3,'유해위험요인 파악'),(4,7,'현재 위험성'),(7,9,'위험성 감소대책')]:
            cell(xs[start],top,xs[end]-xs[start],24,[label],size=9,align='center',bold=True,gray=True,center=True)
        for col,label in {1:'위험분류',2:'위험발생상황',4:'가능성\n(빈도)',5:'중대성\n(강도)',6:'위험성',7:'감소대책',8:'감소대책 방법'}.items():
            cell(xs[col],top-24,model['columns'][col],30,label.split('\n'),size=8,align='center',bold=True,gray=True,center=True)
        top -= 54
        for row in page['rows']:
            for col,lines in enumerate(row['cells']):
                cell(xs[col],top,model['columns'][col],row['height'],lines,size=model['sizes'][col],leading=model['leading'][col],
                     align='center' if col in (0,4,5,6,9,10,11,12) else 'left',center=col in (0,4,5,6,9,10,11,12))
            top -= row['height']
        pdf.setLineWidth(.9);pdf.line(margin,top,margin+table_width,top)
        cell(margin,45,table_width/3,16,['붙임 KECO-P-610-10'],size=8.5,border=False)
        cell(margin+table_width/3,45,table_width/3,16,['한국환경공단'],size=9,align='center',border=False)
        cell(margin+table_width*2/3,45,table_width/3,16,['A4(210mm×297mm)'],size=8.5,align='right',border=False)
        cell(margin,28,table_width,10,[f'{page_number} / {total_pages}'],size=7,align='center',border=False)
        pdf.showPage()
    if execution:
        ra_form16_draw_pdf(pdf, execution, start_page=len(model["pages"]), total_pages=total_pages)
    pdf.save()
    return output.getvalue()



def ra_hwpx(meta, rows, final, include_execution=True):
    """Editable native tables, with the same measured pages as the PDF form."""
    model = ra_form14_layout(meta,rows,final)
    execution = ra_form16_layout(meta,rows,final) if include_execution else None
    total_pages = len(model["pages"])+(len(execution["pages"]) if execution else 0)
    doc = HwpxDocument.new()
    hp = 'http://www.hancom.co.kr/hwpml/2011/paragraph'
    if hasattr(doc,'page'):
        doc.page.setup(paper_size='A4',orientation='LANDSCAPE',margin_left_mm=24*25.4/72,margin_right_mm=24*25.4/72,
                       margin_top_mm=24*25.4/72,margin_bottom_mm=24*25.4/72,header_margin_mm=0,footer_margin_mm=0)
    else:
        page = doc.sections[0].element.find('.//{%s}pagePr'%hp)
        page.set('width','59528');page.set('height','84189');page.set('landscape','NARROWLY')
        margins=page.find('{%s}margin'%hp)
        for key,value in [('left','2400'),('right','2400'),('top','2400'),('bottom','2400'),('header','0'),('footer','0')]:margins.set(key,value)
    styles = doc.styles if hasattr(doc,'styles') else doc
    apply_format = styles.apply_paragraph_format if hasattr(styles,'apply_paragraph_format') else doc.set_paragraph_format
    make_fill = styles.ensure_border_fill if hasattr(styles,'ensure_border_fill') else doc.ensure_border_fill
    plain = make_fill(border_color='#000000',border_width='0.12 mm')
    gray = make_fill(border_color='#000000',border_width='0.12 mm',fill_color='#F1F1F1')
    no_border = make_fill(border_color='#FFFFFF',border_width='0.12 mm',active_borders=[])
    formats = {}
    def paragraph_style(align, percent=137):
        key=(align,percent)
        if key not in formats:
            p=doc.add_paragraph('',para_pr_id_ref='0')
            apply_format(paragraphs=[p],alignment=align,line_spacing_percent=percent,spacing_before_pt=0,spacing_after_pt=0,
                         indent_left_mm=0,indent_right_mm=0,first_line_indent_mm=0)
            formats[key]=p.element.get('paraPrIDRef');p.remove()
        return formats[key]
    # Precreate formats before page blocks so temporary paragraphs cannot split a page.
    for align in ('LEFT','CENTER','RIGHT'):
        for percent in (100,130,137):paragraph_style(align,percent)
    first=doc.paragraphs[0]
    if not first.text.strip():
        first.element.set('paraPrIDRef',paragraph_style('LEFT',100))
        marker=first.add_run('',font='맑은 고딕',size=1)
        for run in first.runs:run.element.set('charPrIDRef',marker.element.get('charPrIDRef'))
    def text(cell,lines,*,size=8,align='LEFT',bold=False,fill=None,center=False,percent=137):
        cell.set_text('')
        cell.element.set('borderFillIDRef',str(fill if fill is not None else plain))
        cell.element.set('hasMargin','1')
        margin=cell.element.find('{%s}cellMargin'%hp)
        if margin is not None:
            for name in ('left','right','top','bottom'):margin.set(name,'400')
        sublist=cell.element.find('{%s}subList'%hp)
        sublist.set('vertAlign','CENTER' if center else 'TOP')
        # Lines are already measured and explicitly separated. Hancom fits each
        # line to its cell rather than rewrapping it with a substitute font.
        sublist.set('lineWrap','SQUEEZE')
        for index,line in enumerate(lines or ['']):
            p=cell.paragraphs[0] if index==0 else cell.add_paragraph('')
            p.element.set('paraPrIDRef',paragraph_style(align,percent));p.element.set('styleIDRef','0')
            # Empty template runs otherwise impose a 10pt minimum line height.
            for run in list(p.runs):p.element.remove(run.element)
            p.add_run(line,font='맑은 고딕',size=size,bold=bold)
    def table(widths,heights,*,new_page=False,fill=None):
        widths=[round(v*100) for v in widths];heights=[round(v*100) for v in heights]
        obj=doc.add_table(rows=len(heights),cols=len(widths),width=sum(widths),height=sum(heights),
                          border_fill_id_ref=fill if fill is not None else plain,para_pr_id_ref=paragraph_style('LEFT',100))
        obj.element.set('pageBreak','NONE');obj.element.set('repeatHeader','0')
        p=obj.paragraph
        if new_page:apply_format(paragraphs=[p],page_break_before=True)
        for r,height in enumerate(heights):
            for c,width in enumerate(widths):obj.cell(r,c).set_size(width=width,height=height)
        return obj
    width=model['table_width']
    for page_number,page in enumerate(model['pages'],1):
        top=table([88,width-88],[16],new_page=page_number>1,fill=no_border)
        text(top.cell(0,0),[''],size=9,fill=no_border,center=True,percent=100)
        meta_lines=ra_form14_wrap(model['meta_line'],width-96,7.1)
        text(top.cell(0,1),meta_lines,size=7.1,align='RIGHT',fill=no_border,center=True,percent=100)
        title=table(model['info_widths'],[30,page['info_height']])
        title.merge_cells(0,0,0,7)
        text(title.cell(0,0),['위험성평가(위험성 결정)'],size=16,align='CENTER',bold=True,fill=gray,center=True,percent=100)
        for col,lines in enumerate(page['info']):
            text(title.cell(1,col),lines,size=8,align='CENTER' if col%2==0 else 'LEFT',bold=col%2==0,
                 fill=gray if col%2==0 else plain,center=True,percent=130)
        grid=table(model['columns'],[24,30]+[row['height'] for row in page['rows']])
        for col in (0,3,9,10,11,12):grid.merge_cells(0,col,1,col)
        for start,end in ((1,2),(4,6),(7,8)):grid.merge_cells(0,start,0,end)
        for col,label in {0:'번\n호',3:'현재의\n안전보건조치',9:'개선후\n위험성',10:'개선\n예정일',11:'개선\n완료일',12:'담당자',
                          1:'유해위험요인 파악',4:'현재 위험성',7:'위험성 감소대책'}.items():
            text(grid.cell(0,col),label.split('\n'),size=7.5 if col in (0,3,9,10,11,12) else 9,
                 align='CENTER',bold=True,fill=gray,center=True,percent=100)
        for col,label in {1:'위험분류',2:'위험발생상황',4:'가능성\n(빈도)',5:'중대성\n(강도)',6:'위험성',7:'감소대책',8:'감소대책 방법'}.items():
            text(grid.cell(1,col),label.split('\n'),size=8,align='CENTER',bold=True,fill=gray,center=True,percent=100)
        for index,row in enumerate(page['rows'],2):
            for col,lines in enumerate(row['cells']):
                centered=col in (0,4,5,6,9,10,11,12)
                text(grid.cell(index,col),lines,size=model['sizes'][col],align='CENTER' if centered else 'LEFT',center=centered)
        footer=table([width/3]*3,[27],fill=no_border)
        for col,label in enumerate(['붙임 KECO-P-610-10',f'한국환경공단\n{page_number} / {total_pages}','A4(210mm×297mm)']):
            text(footer.cell(0,col),label.split('\n'),size=8,align=['LEFT','CENTER','RIGHT'][col],fill=no_border,center=True,percent=100)
    if execution:
        ra_form16_append_hwpx(doc,execution,start_page=len(model["pages"]),total_pages=total_pages)
    output=io.BytesIO();doc.save_to_stream(output)
    return output.getvalue()



def ra_render_sharing(meta, actor):
    meta['report_mode'] = '출력본'
    st.info('공단 작성자가 내용을 확인해 보고서를 만듭니다. 결재는 PDF·한글 보고서를 출력한 뒤 지면으로 진행합니다.')
    meta.setdefault('execution_supervisor','')
    with st.expander('현장 전달·후속 점검 기록 (선택)'):
        left,right=st.columns(2)
        with left:
            ra_field('전달 상태','sharing_state',kind='select',options=['공유 예정','공유 완료'])
            ra_field('전달일·예정일','sharing_date',kind='date')
        with right:ra_field('전달 방법','sharing_method',kind='select',options=['TBM','현장 게시','교육','회의·메신저','기타'])
    with st.expander('보고서에 반영할 평가 항목 확인',expanded=True):ra_overview(meta,st.session_state.ra_rows)
    missing=ra_validation_issues(meta,st.session_state.ra_rows,True)
    if missing:
        st.warning(f'보고서 작성 전 확인할 항목 {len(missing)}개')
    else:st.success('주요 작성 항목을 입력했습니다. 보고서를 만들 수 있습니다.')
    ra_render_validation_links(missing, actor)
    st.caption('위험성평가표와 감소대책 수립·이행결과를 함께 작성합니다. A4 가로 방향이며 이행결과는 한 장에 최대 2개 항목을 배치합니다. 사진이 없으면 미등록으로 표시합니다.')
    payload = ra_payload(); sig = ra_hash([RA_FORM14_VERSION, payload])
    if st.button('위험성평가 보고서 만들기', type='primary', key='ra_build'):
        errors = ra_validate(meta, st.session_state.ra_rows, payload['final'])
        if errors:
            st.warning('위 미작성 항목을 눌러 필요한 내용을 보완해 주세요.')
        else:
            previous = st.session_state.get('ra_output', {})
            outputs = dict(previous) if previous.get('sig') == sig else {'sig': sig}
            with keco_loading('위험성평가표와 이행결과 보고서를 만들고 있습니다…', kind='steps', steps=('PDF 작성', '한글 작성', '보고서 보관')):
                if not outputs.get('pdf'):
                    keco_loading_stage(0)
                    try: outputs['pdf'] = ra_pdf(meta, st.session_state.ra_rows, payload['final'])
                    except ValueError as exc: st.error(str(exc))
                    except Exception: st.error('PDF 생성 실패. 글꼴·문서 라이브러리 확인 필요.')
                if not outputs.get('hwpx'):
                    keco_loading_stage(1)
                    try: outputs['hwpx'] = ra_hwpx(meta, st.session_state.ra_rows, payload['final'])
                    except ValueError as exc: st.error(str(exc))
                    except Exception: st.error('한글 생성 실패. HWPX 라이브러리 확인 필요.')
                file_sig = ra_hash([sig, bool(outputs.get('hwpx')), bool(outputs.get('pdf'))])
                if (outputs.get('hwpx') or outputs.get('pdf')) and outputs.get('archived_files_sig') != file_sig:
                    try:
                        keco_loading_stage(2)
                        ra_archive(actor, payload)
                        ra_archive_report(actor,st.session_state.ra_active_record_id,'risk:'+str(actor)+':'+sig,outputs.get('hwpx'),outputs.get('pdf'))
                        st.session_state.ra_last_saved_sig = ra_hash(payload)
                        outputs['archived_files_sig'] = file_sig
                    except ValueError as exc: st.warning(str(exc))
                    except Exception: st.warning('보고서는 생성했으나 저장소 보관 확인 필요. 다운로드해 보관해 주세요.')
            st.session_state.ra_output = outputs
    outputs = st.session_state.get('ra_output', {})
    if outputs.get('sig') == sig:
        if outputs.get('pdf'): st.download_button('평가표·이행결과 PDF 다운로드', outputs['pdf'], '위험성평가_및_이행결과_보고서.pdf', 'application/pdf', key='ra_pdf_download', on_click='ignore')
        if outputs.get('hwpx'): st.download_button('평가표·이행결과 한글 다운로드', outputs['hwpx'], '위험성평가_및_이행결과_보고서.hwpx', 'application/hwp+zip', key='ra_hwpx_download', on_click='ignore')
    elif outputs: st.caption('작성 내용이 바뀌었습니다. 보고서를 다시 만들어 주세요.')



RA_KINDS = ['최초평가', '정기평가', '수시평가']
RA_METHOD = '빈도·강도법'
RA_OTHER_METHODS = ['위험성 수준 3단계 판단법', '체크리스트법', '핵심요인 기술법', '산업별 평가']
