def ra_hub_select_page(record_ids, key):
    selected = set(st.session_state.get('ra_hub_selection', []))
    if st.session_state.get(key): selected.update(record_ids)
    else: selected.difference_update(record_ids)
    st.session_state.ra_hub_selection = sorted(selected)
    st.session_state.ra_hub_delete_confirm = False
    st.session_state.ra_hub_focus_id=None


def ra_hub_open_selected(actor):
    record_id=ra_hub_open_target()
    if not record_id:
        st.session_state.ra_load_error='작성할 평가를 한 건 선택해 주세요.'
        return
    ra_hub_open(actor,record_id)


def ra_hub_request_delete():
    st.session_state.ra_hub_delete_confirm = True


def ra_hub_cancel_delete():
    st.session_state.ra_hub_delete_confirm = False


def ra_hub_edit_selected(actor):
    selected = st.session_state.get('ra_hub_selection', [])
    if len(selected) != 1:
        st.session_state.ra_load_error = '수정할 평가를 한 건 선택해 주세요.'
        return
    try:
        record = ra_record_load(actor, selected[0])
        meta = record['payload']['meta']
        st.session_state.ra_hub_edit_record = record
        st.session_state.ra_hub_edit_name = meta.get('assessment_name', '')
        st.session_state.ra_hub_edit_site = meta.get('site', '')
        st.session_state.ra_hub_edit_kind = meta.get('kind', RA_KINDS[0])
        st.session_state.ra_hub_edit_year = ra_assessment_year(meta.get('assessment_year'))
        st.session_state.ra_hub_page = 'edit'
    except (ValueError, PermissionError, json.JSONDecodeError) as exc:
        st.session_state.ra_load_error = str(exc)
    except Exception:
        st.session_state.ra_load_error = '평가 정보를 불러오지 못했습니다. 저장소 연결을 확인해 주세요.'


def ra_hub_commit_edit(actor):
    import copy
    try:
        record = st.session_state.get('ra_hub_edit_record')
        if not record: raise ValueError('목록에서 수정할 평가를 다시 선택해 주세요.')
        data = copy.deepcopy(record['payload'])
        data['meta'].update(assessment_year=str(ra_assessment_year(st.session_state.get('ra_hub_edit_year'))),
                            site=st.session_state.get('ra_hub_edit_site', '').strip(),
                            kind=st.session_state.get('ra_hub_edit_kind'))
        if any(data['meta'].get(field)!=record['payload']['meta'].get(field) for field in ('site','assessment_year','kind')):
            data['meta']['assessment_name']=ra_auto_name(data['meta'])
        department = ra_site_department(data['meta']['site'])
        if department: data['meta']['department'] = department
        if data['meta'] != record['payload']['meta']:
            data['meta']['review_confirmed'] = False
            data['meta']['review_sig'] = ''
            data['final'] = False
        ra_record_save(actor, record['id'], data, record['revision'], record['step'])
        st.session_state.ra_hub_edit_record = None
        st.session_state.ra_hub_site_info = None
        st.session_state.ra_hub_page = 'list'
        st.session_state.ra_notice = '평가 정보를 수정했습니다. 기존 평가 항목과 작성 내용은 보존됩니다.'
    except (ValueError, PermissionError) as exc:
        st.session_state.ra_load_error = str(exc)
    except Exception:
        st.session_state.ra_load_error = '수정 내용을 저장하지 못했습니다. 입력 내용은 유지됩니다. 저장소 연결을 확인해 주세요.'


def ra_render_record_edit(actor):
    st.markdown(RA_REGISTER_LIST_CSS,unsafe_allow_html=True)
    record=st.session_state.get('ra_hub_edit_record')
    if not record:
        st.warning('목록에서 수정할 평가를 선택해 주세요.')
        st.button('← 목록',key='ra_hub_edit_missing_back',on_click=ra_hub_navigate,args=('list',))
        return
    st.subheader('위험성평가 정보 수정')
    meta=record['payload']['meta']
    st.session_state.setdefault('ra_hub_edit_year',ra_assessment_year(meta.get('assessment_year')))
    with st.container(border=True,key='ra_hub_edit_card'):
        year,kind=st.columns(2)
        with year:st.selectbox('평가연도 *',ra_year_options(extra=[st.session_state.ra_hub_edit_year]),key='ra_hub_edit_year',format_func=lambda v:str(v)+'년',on_change=ra_hub_edit_context_change)
        with kind:st.selectbox('평가구분 *',RA_KINDS,key='ra_hub_edit_kind',on_change=ra_hub_edit_context_change)
        st.selectbox('사업장명',([''] if not meta.get('site') else [])+ra_site_options(extra=[meta.get('site'),st.session_state.get('ra_hub_edit_site')]),key='ra_hub_edit_site',index=None,on_change=ra_hub_edit_context_change)
        st.caption('평가방법 · '+meta.get('method',RA_METHOD))
    save,cancel=st.columns(2)
    with save:st.button('수정 저장',key='ra_hub_edit_save',type='primary',on_click=ra_hub_commit_edit,args=(actor,),width='stretch')
    with cancel:st.button('취소 · 목록',key='ra_hub_edit_cancel',on_click=ra_hub_navigate,args=('list',),width='stretch')


def ra_hub_show_site_info(actor, record_id):
    try:
        record = ra_record_load(actor, record_id)
        meta = record['payload']['meta']
        st.session_state.ra_hub_site_info = {label: str(meta.get(key, '') or '미입력') for label, key in
            [('사업장명', 'site'), ('담당부서', 'department'), ('현장 주소', 'address'), ('수행기관·시공사', 'company')]}
    except (ValueError, PermissionError, json.JSONDecodeError) as exc:
        st.session_state.ra_load_error = str(exc)
    except Exception:
        st.session_state.ra_load_error = '사업장 정보를 확인하지 못했습니다. 저장소 연결을 확인해 주세요.'


def ra_hub_close_site_info():
    st.session_state.ra_hub_site_info = None


def ra_render_history(actor):
    from html import escape
    st.markdown(RA_REGISTER_LIST_CSS, unsafe_allow_html=True)
    st.html(RA_ORIGINAL_CSS)
    with st.container(key='ra_hub_list_toolbar'):
        title, guide, area_box = st.columns([5, 1.8, 1.5], gap='small')
        with title:
            with st.container(key='ra_register_title'): st.subheader('위험성평가 실시')
        with guide:
            st.button('평가방법 안내', key='ra_hub_history_guide', on_click=ra_hub_navigate, args=('guide',), width='stretch')
        with area_box:
            area = st.selectbox('보관 상태', ['평가 목록', '휴지통'], key='ra_hub_area',
                                on_change=ra_hub_filter_reset, label_visibility='collapsed')
    trashed = area == '휴지통'
    try:
        records = ra_record_list(actor, trashed)
    except (ValueError, PermissionError) as exc:
        st.error(str(exc)); return
    except Exception:
        st.error('평가 목록을 불러오지 못했습니다. 저장소 연결을 확인한 뒤 새로고침해 주세요.')
        st.button('목록 새로고침', key='ra_hub_list_retry'); return
    current_year = ra_current_year()
    defaults = dict(year=str(current_year), kind='전체', site='전체', name='전체', query='')
    filters = dict(defaults, **st.session_state.get('ra_hub_filters', {}))
    # Old free-text filters become explicit selectors on the first updated visit.
    if 'ra_hub_filter_site' not in st.session_state:
        filters.update(site='전체', name='전체', query='')
        st.session_state.ra_hub_filters = filters
    years = ['전체'] + [str(v) for v in ra_year_options(records)]
    sites = ['전체'] + ra_site_options(records)
    with st.container(key='ra_hub_filters_box'):
        with st.container(key='ra_hub_filter_fields'):
            year, kind, site, name, search, reset = st.columns([1, 1.05, 2.4, 2.4, .75, .75], gap='small')
        with year:
            st.session_state.setdefault('ra_hub_filter_year', str(filters['year']))
            if st.session_state.ra_hub_filter_year not in years:
                st.session_state.ra_hub_filter_year = str(current_year)
            st.selectbox('연도', years, key='ra_hub_filter_year', format_func=lambda v: v if v == '전체' else v+'년', on_change=ra_hub_filter_context_change)
        with kind:
            st.session_state.setdefault('ra_hub_filter_kind', filters['kind'])
            if st.session_state.ra_hub_filter_kind not in ['전체']+RA_KINDS:
                st.session_state.ra_hub_filter_kind = '전체'
            st.selectbox('평가구분', ['전체']+RA_KINDS, key='ra_hub_filter_kind', on_change=ra_hub_filter_context_change)
        with site:
            st.session_state.setdefault('ra_hub_filter_site', filters['site'])
            if st.session_state.ra_hub_filter_site not in sites:
                st.session_state.ra_hub_filter_site = '전체'
            st.selectbox('사업장명', sites, key='ra_hub_filter_site', on_change=ra_hub_filter_context_change)
        with name:
            names = ['전체'] + ra_hub_search_names(records, st.session_state.ra_hub_filter_year,
                        st.session_state.ra_hub_filter_kind, st.session_state.ra_hub_filter_site)
            st.session_state.setdefault('ra_hub_filter_name', filters['name'])
            if st.session_state.ra_hub_filter_name not in names:
                st.session_state.ra_hub_filter_name = '전체'
                filters['name'] = '전체'
            st.selectbox('평가명', names, key='ra_hub_filter_name', on_change=ra_hub_filter)
        with search:
            st.button('검색', key='ra_hub_search', on_click=ra_hub_filter, type='primary', width='stretch')
        with reset:
            st.button('초기화', key='ra_hub_reset', on_click=ra_hub_filter_reset, width='stretch')
    filters = dict(defaults, **st.session_state.get('ra_hub_filters', filters))
    visible = [r for r in records
        if (filters['year'] == '전체' or str(r['assessment_year']) == str(filters['year']))
        and (filters['kind'] == '전체' or r['kind'] == filters['kind'])
        and (filters['site'] == '전체' or r['site'] == filters['site'])
        and (filters['name'] == '전체' or r['name'] == filters['name'])]
    page_count = max(1, (len(visible)+9)//10)
    page = max(1, min(page_count, st.session_state.get('ra_hub_page_number', 1)))
    st.session_state.ra_hub_page_number = page
    page_records = visible[(page-1)*10:page*10]
    if trashed or st.session_state.get('ra_hub_focus_id') not in {row['id'] for row in page_records}:
        st.session_state.ra_hub_focus_id=None
    focused=st.session_state.get('ra_hub_focus_id')
    selected = set(st.session_state.get('ra_hub_selection', [])) & {r['id'] for r in visible}
    st.session_state.ra_hub_selection = sorted(selected)
    with st.container(key='ra_hub_actions'):
        count, open_box, register, original, edit, delete = st.columns([2.5, 1.7, 1, 1.7, 1, 1], gap='small')
        with count:
            label = '휴지통' if trashed else '목록'
            st.markdown(f'<p class="ra-register-count">{label} (총 {len(visible)}건)<small>체크 {len(selected)}건{(" · 열기 대상 1건" if focused and not selected else "")}</small></p>', unsafe_allow_html=True)
        with open_box:
            if trashed:
                st.button('선택 평가 복원', key='ra_hub_restore', disabled=not selected, type='primary',
                          on_click=ra_hub_change_trash, args=(actor, True), width='stretch')
            else:
                st.button('선택한 평가 열기', key='ra_hub_open_selected', disabled=not bool(ra_hub_open_target()), type='primary',
                          on_click=ra_hub_open_selected, args=(actor,), width='stretch')
        with register:
            st.button('＋ 등록', key='ra_hub_new', disabled=trashed, type='primary' if not selected else 'secondary', on_click=ra_hub_navigate, args=('registration',), width='stretch')
        with original:
            st.button('기존 보고서 등록', key='ra_hub_original_new', disabled=trashed, on_click=ra_hub_navigate, args=('import',), width='stretch')
        with edit:
            st.button('수정', key='ra_hub_edit_selected', disabled=trashed or len(selected)!=1,
                      on_click=ra_hub_edit_selected, args=(actor,), width='stretch')
        with delete:
            if trashed:
                st.button('완전삭제',key='ra_hub_request_purge',disabled=not selected,on_click=ra_hub_request_purge,width='stretch')
            else:
                st.button('삭제',key='ra_hub_request_delete',disabled=not selected,on_click=ra_hub_request_delete,width='stretch')
    purge_ids=st.session_state.get('ra_hub_purge_ids',[])
    if trashed and purge_ids and set(purge_ids)==selected:
        with st.container(border=True,key='ra_hub_purge_panel'):
            st.warning(f'평가 {len(purge_ids)}건을 완전삭제합니다. 삭제 후 복원할 수 없습니다.')
            for record in records:
                if record['id'] in purge_ids:st.write('• '+record['site']+' / '+str(record['assessment_year'])+'년 / '+record['kind'])
            st.caption('평가 작성자료와 연결된 보고서를 삭제합니다. 다른 자료에서 사용하는 공용 파일과 별도 다운로드한 파일은 유지됩니다.')
            acknowledged=st.checkbox('선택한 평가와 연결된 보고서를 복원할 수 없음을 확인합니다.',key='ra_hub_purge_ack')
            confirm,cancel=st.columns(2)
            with confirm:st.button('완전삭제 실행',key='ra_hub_purge_confirm',type='primary',disabled=not acknowledged,on_click=ra_hub_confirm_purge,args=(actor,),width='stretch')
            with cancel:st.button('취소',key='ra_hub_purge_cancel',on_click=ra_hub_cancel_purge,width='stretch')
    if st.session_state.get('ra_hub_cleanup_pending'):
        st.caption('일부 보고서 파일 정리가 남아 있습니다. 저장소 연결·삭제 권한을 확인한 뒤 다시 시도해 주세요.')
        st.button('남은 보고서 파일 정리',key='ra_hub_cleanup_retry',on_click=ra_hub_retry_cleanup)
    if not trashed and selected and st.session_state.get('ra_hub_delete_confirm'):
        with st.container(border=True, key='ra_hub_delete_panel'):
            st.write(f'선택한 평가 {len(selected)}건을 삭제하시겠습니까? 삭제한 평가는 휴지통에서 복원할 수 있습니다.')
            confirm, cancel = st.columns(2)
            with confirm:
                st.button('삭제 확인', key='ra_hub_delete', on_click=ra_hub_change_trash, args=(actor, False), width='stretch')
            with cancel:
                st.button('취소', key='ra_hub_delete_cancel', on_click=ra_hub_cancel_delete, width='stretch')
    st.caption('등록일·사업장명·평가명을 클릭하면 체크되고, 같은 항목을 다시 클릭하면 해제됩니다. 여러 평가는 체크박스로 선택하세요.' if not trashed else '평가를 체크한 뒤 복원 또는 완전삭제를 선택하세요.')
    with st.container(key='ra_hub_table'):
        with st.container(key='ra_table_header'):
            columns = st.columns(9, gap='small', vertical_alignment='center')
            headings = ['No.', '', '등록일', '사업장명', '위험성평가명', '평가구분', '평가방법', '진행상태', '사업장정보']
            for index, heading in enumerate(headings):
                with columns[index]:
                    if index == 1:
                        ids = [r['id'] for r in page_records]
                        st.session_state.ra_hub_select_all = bool(ids) and set(ids).issubset(selected)
                        st.checkbox('현재 페이지 전체 선택', key='ra_hub_select_all', disabled=not ids, label_visibility='collapsed',
                                    on_change=ra_hub_select_page, args=(ids, 'ra_hub_select_all'))
                    else:
                        st.markdown(heading)
        if not page_records:
            message = '검색 조건에 맞는 평가가 없습니다.' if records else ('휴지통이 비어 있습니다.' if trashed else '등록된 위험성평가가 없습니다. 위의 ‘＋ 등록’을 눌러 등록하세요.')
            st.markdown('<div class="ra-table-empty">'+escape(message)+'</div>', unsafe_allow_html=True)
        for number, record in enumerate(page_records, (page-1)*10+1):
            record_id = record['id']
            with st.container(key='ra_hub_row_'+record_id):
                columns = st.columns(9, gap='small', vertical_alignment='center')
                fields = [number, None, str(record['created'])[:10], record['site'] or '미입력', record['name'],
                          record['kind'], record['method'], record['status']]
                for index, value in enumerate(fields):
                    with columns[index]:
                        if index == 1:
                            key = 'ra_hub_checked_'+record_id
                            st.session_state[key] = record_id in selected
                            st.checkbox(f'평가 {number} 선택', key=key, label_visibility='collapsed',
                                        on_change=ra_hub_select, args=(record_id, key))
                        elif index in (2,3,4):
                            prefix='ra_hub_focuscell_active_' if record_id==focused else 'ra_hub_focuscell_'
                            with st.container(key=prefix+str(index)+'_'+record_id):
                                st.button(ra_hub_cell_label(value),key='ra_hub_focus_'+str(index)+'_'+record_id,disabled=trashed,
                                          on_click=ra_hub_focus_record,args=(record_id,),width='stretch')
                        elif index == 7:
                            if not trashed and value in ('출력본 작성', '기존 보고서 등록'):
                                try:
                                    file = ra_record_download(actor, record_id)
                                    st.download_button(str(value), file['data'], file['filename'], file['mime'],
                                                       key='ra_hub_report_download_'+record_id, on_click='ignore',
                                                       help='클릭하면 위험성평가 보고서를 내려받습니다.', width='stretch')
                                except Exception:
                                    st.markdown('<span class="ra-table-status">'+escape(str(value))+'</span>', unsafe_allow_html=True)
                                    st.caption('파일 확인 필요 · 평가를 열어 다시 저장해 주세요.')
                            else:
                                st.markdown('<span class="ra-table-status">'+escape(str(value))+'</span>', unsafe_allow_html=True)
                        else:
                            style = 'name' if index == 4 else ('center' if index in (0, 2, 5, 6) else '')
                            st.markdown('<p class="ra-table-cell '+style+'">'+escape(str(value))+'</p>', unsafe_allow_html=True)
                with columns[8]:
                    st.button('정보', key='ra_hub_site_'+record_id, disabled=trashed,
                              on_click=ra_hub_show_site_info, args=(actor, record_id), width='stretch')
    if visible:
        with st.container(key='ra_hub_pagination'):
            left, label, right = st.columns([1, 2, 1], gap='small')
            with left:
                st.button('이전', key='ra_hub_page_previous', disabled=page==1, on_click=ra_hub_page_move, args=(page-1,), width='stretch')
            with label:
                st.markdown(f'<div class="ra-page-counter">{page} / {page_count}페이지</div>', unsafe_allow_html=True)
            with right:
                st.button('다음', key='ra_hub_page_next', disabled=page==page_count, on_click=ra_hub_page_move, args=(page+1,), width='stretch')
    info = st.session_state.get('ra_hub_site_info')
    if info and not trashed:
        with st.container(border=True, key='ra_hub_site_info_panel'):
            st.markdown('#### 사업장 정보')
            for label, value in info.items(): st.write(label+' · '+value)
            st.button('정보 닫기', key='ra_hub_site_close', on_click=ra_hub_close_site_info)





def ra_render_standard_models(meta, trade, work, examples):
    with st.expander('표준모델 참고하기', expanded=True):
        st.caption('선택한 표준모델의 유해위험요인과 감소대책을 참고할 수 있습니다.')
        ids = [model['id'] for model in examples]
        labels = {model['id']: model['title'] for model in examples}
        pick_key = 'ra_model_picks_'+ra_hash([trade, ids])[:12]
        picked = st.multiselect('참고할 표준모델 (여러 개 선택 가능)', ids, key=pick_key, format_func=labels.__getitem__)
        if not examples:
            st.info('참고할 표준모델이 없습니다.')
        preview_ids = picked or ids[:1]
        previews = [model for eid in preview_ids for model in examples if model['id'] == eid]
        for model in previews:
            with st.container(key='ra_model_preview_'+model['id']):
                st.markdown('**'+model['title']+'**')
                st.write('유해위험요인 · '+model['factor'])
                for kind, detail in model['controls']:
                    st.write('• '+kind+' / '+detail)
                if model.get('incident'):
                    st.caption('사고사례 요약 · '+model['incident'])
        return previews


def ra_render_writer(actor):
    if not st.session_state.get('ra_active_record_id'):
        st.session_state.ra_hub_page = 'list'
        st.info('목록에서 작성할 평가를 선택해 주세요.')
        return
    st.markdown(RA_REVIEW_CSS, unsafe_allow_html=True)
    meta, rows = st.session_state.ra_meta, st.session_state.ra_rows
    st.subheader((meta.get('site') or '현장')+' 위험성평가 작성')
    st.caption(str(meta.get('assessment_year',''))+'년 · '+meta['kind']+' · '+RA_METHOD+' · 작성 후 보고서 출력·지면 결재')
    back, guide, save = st.columns([1, 2, 1])
    with back: st.button('← 목록', key='ra_hub_writer_back', on_click=ra_hub_back, args=(actor,), width='stretch')
    with guide: st.button('평가구분·평가방법 안내', key='ra_hub_writer_guide', on_click=ra_hub_navigate, args=('guide',), width='stretch')
    with save: st.button('임시 저장', key='ra_save', on_click=ra_hub_save, args=(actor,), type='primary', width='stretch')
    st.caption('입력은 단계 이동 중 유지됩니다. ‘임시 저장’ 또는 ‘목록’을 누르면 저장소에 반영됩니다.')
    ra_field('공사종류', 'construction_type', kind='select', options=[None]+RA_CONSTRUCTION_TYPES, disabled=meta.get('construction_type') in RA_CONSTRUCTION_TYPES, format_func=lambda value: '공사종류를 선택하세요' if value is None else value)
    if meta.get('legacy_construction_type') and not meta['construction_type']:
        st.caption('기존 공사종류 · '+meta['legacy_construction_type']+' / 새 분류에서 공사종류를 선택해 주세요. 기존 평가 항목은 유지됩니다.')
    if not meta['construction_type']:
        st.info('먼저 공사종류를 선택하면 단계별 작성 화면이 열립니다.')
        return
    ready = ra_progress(meta, rows)
    st.progress(sum(ready)/6, text=f'작성 확인 {sum(ready)}/6단계 · 평가 항목 {len(rows)}개')
    step = st.radio('작성 순서', RA_STEPS, horizontal=True, key='ra_step', on_change=ra_remember_step)
    index = RA_STEPS.index(step)
    st.markdown('### '+step)
    if index == 0: ra_render_preparation(meta, actor)
    elif index == 1: ra_render_identification(meta)
    elif index == 2: ra_render_rating(meta)
    elif index == 3: ra_render_measures(meta)
    elif index == 4: ra_render_execution(meta)
    else: ra_render_sharing(meta, actor)
    st.divider()
    previous, next_step = st.columns(2)
    with previous:
        if index == 0:
            st.button('이전 단계', on_click=ra_hub_back, args=(actor,), key='ra_previous', width='stretch')
        else:
            st.button('이전 단계', on_click=ra_go_step, args=(index-1,), key='ra_previous', width='stretch')
    with next_step:
        if index < len(RA_STEPS)-1:
            st.button('다음 단계', on_click=ra_go_step, args=(index+1,), key='ra_next', width='stretch')
        else:
            st.button('최종 저장하고 목록으로 돌아가기', on_click=ra_hub_finalize, args=(actor,), key='ra_finalize_back', type='primary', width='stretch')
    if st.session_state.get('ra_hub_reload_needed'):
        with st.expander('저장된 최신 내용 불러오기', expanded=True):
            st.caption('다른 창의 변경사항을 불러오면 현재 화면의 미저장 입력이 바뀝니다. 필요한 내용을 확인한 뒤 진행하세요.')
            confirmed = st.checkbox('현재 화면을 저장된 최신 내용으로 바꿉니다.', key='ra_hub_reload_confirm')
            st.button('최신 내용 불러오기', key='ra_hub_writer_reload', disabled=not confirmed,
                      on_click=ra_hub_open, args=(actor, st.session_state.ra_active_record_id))
    ra_render_issue_focus()


def ra_hardware_back(actor):
    """Use the same authenticated navigation and storage as the on-screen buttons."""
    if not actor or not st.session_state.get('password_correct'):
        return
    page = st.session_state.get('ra_hub_page', 'list')
    if page == 'guide':
        ra_hub_navigate(st.session_state.get('ra_hub_return', 'list'))
    elif page in ('edit', 'import', 'original'):
        ra_hub_navigate('list')
    elif page == 'registration':
        ra_hub_registration_change()
        ra_hub_navigate('list')
    elif page == 'writer':
        step = st.session_state.get('ra_step', RA_STEPS[0])
        index = RA_STEPS.index(step) if step in RA_STEPS else 0
        if index:
            ra_go_step(index-1)
            if not ra_hub_save(actor, quiet=True):
                ra_go_step(index)
        else:
            ra_hub_back(actor)
    elif st.session_state.get('ra_hub_area') == '휴지통':
        st.session_state.ra_hub_area = '평가 목록'
        ra_hub_filter_reset()
    elif st.session_state.get('ra_hub_page_number', 1) > 1:
        ra_hub_page_move(st.session_state.ra_hub_page_number-1)
    st.session_state.keco_back_revision = st.session_state.get('keco_back_revision', 0)+1


def render_risk_back_bridge(actor):
    page = st.session_state.get('ra_hub_page', 'list')
    can_back = page in ('writer', 'registration', 'guide', 'edit') or st.session_state.get('ra_hub_area') == '휴지통' or st.session_state.get('ra_hub_page_number', 1) > 1
    st.markdown('<style>.st-key-keco_hardware_back{display:none!important;}</style>', unsafe_allow_html=True)
    with st.container(key='keco_hardware_back'):
        st.markdown('<span id="keco-risk-navigation" data-back="'+('yes' if can_back else 'no')+'" data-revision="'+str(st.session_state.get('keco_back_revision', 0))+'"></span>', unsafe_allow_html=True)
        st.button('휴대폰 뒤로가기 처리', key='keco_hardware_back_button', on_click=ra_hardware_back, args=(actor,))


