def ptw_today():
    return datetime.datetime.now(ZoneInfo('Asia/Seoul')).date().isoformat()


def ptw_default():
    import uuid
    return dict(schema_version=1, id=uuid.uuid4().hex,
        meta=dict(project='', address='', trade=None, subtrade='', date=ptw_today(), place='',
                  company='', author='', reviewer='', approver='', department='', contact=''),
        works=[], review=dict(instructions='', treatment='', changes='', confirmed=False))


def ptw_validate(data):
    import copy
    if not isinstance(data, dict) or data.get('schema_version') != 1:
        raise ValueError('작업계획서 형식을 확인해 주세요.')
    data = copy.deepcopy(data)
    if not re.fullmatch(r'[a-f0-9]{32}', str(data.get('id', ''))):
        raise ValueError('작업계획서 식별자를 확인해 주세요.')
    if not isinstance(data.get('meta'), dict) or not isinstance(data.get('review'), dict):
        raise ValueError('기본정보·검토정보 형식을 확인해 주세요.')
    if not isinstance(data.get('works'), list) or len(data['works']) > 20:
        raise ValueError('세부 작업은 한 계획서에 20개까지 작성할 수 있습니다.')
    for value in data['meta'].values():
        if value is not None and (not isinstance(value, str) or len(value) > 1000):
            raise ValueError('기본정보 입력 길이를 확인해 주세요.')
    data['meta']['project'] = canonical_site_label(data['meta'].get('project', ''))
    datetime.date.fromisoformat(data['meta']['date'])
    ids = set()
    for work in data['works']:
        if not isinstance(work, dict) or work.get('trade') not in PTW_TRADES:
            raise ValueError('세부 작업의 공종을 확인해 주세요.')
        if work.get('id') in ids or not re.fullmatch(r'[a-f0-9]{32}', str(work.get('id', ''))):
            raise ValueError('세부 작업 식별자를 확인해 주세요.')
        ids.add(work['id'])
        for key in ('name', 'place', 'responsible', 'safety_manager', 'details', 'risk', 'controls', 'measurements'):
            if not isinstance(work.get(key), str) or len(work[key]) > 12000:
                raise ValueError('세부 작업 입력 길이를 확인해 주세요.')
        datetime.date.fromisoformat(work['start_date']); datetime.date.fromisoformat(work['end_date'])
        datetime.time.fromisoformat(work['start']); datetime.time.fromisoformat(work['end'])
        if not isinstance(work.get('workers'), int) or isinstance(work['workers'], bool) or not 0 <= work['workers'] <= 10000:
            raise ValueError('근로자 수를 확인해 주세요.')
        if not isinstance(work.get('hazards'), list) or any(h not in PTW_HAZARDS for h in work['hazards']):
            raise ValueError('유해·위험작업 분류를 확인해 주세요.')
        if not isinstance(work.get('checks'), dict) or any(v not in PTW_CHECK_STATES for v in work['checks'].values()):
            raise ValueError('안전조치 확인 상태를 확인해 주세요.')
    for key in ('instructions', 'treatment', 'changes'):
        if not isinstance(data['review'].get(key), str) or len(data['review'][key]) > 12000:
            raise ValueError('검토·보완사항 입력 길이를 확인해 주세요.')
    if not isinstance(data['review'].get('confirmed'), bool):
        raise ValueError('검토 확인 상태를 확인해 주세요.')
    return data


def ptw_fingerprint(data):
    return hashlib.sha256(json.dumps(data, ensure_ascii=False, sort_keys=True, allow_nan=False).encode()).hexdigest()


def ptw_record_schema(db):
    db.execute('''CREATE TABLE IF NOT EXISTS work_permit_plans (
        id TEXT PRIMARY KEY, owner TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL,
        project TEXT NOT NULL, trade TEXT NOT NULL, work_date TEXT NOT NULL, payload TEXT NOT NULL,
        revision INTEGER NOT NULL DEFAULT 1)''')
    db.execute('CREATE INDEX IF NOT EXISTS work_permit_owner_updated ON work_permit_plans(owner,updated)')


def ptw_record_save(actor, data, revision=None):
    actor = report_history_identity(actor)
    data = ptw_validate(data)
    now = datetime.datetime.now(ZoneInfo('Asia/Seoul')).isoformat()
    encoded = json.dumps(data, ensure_ascii=False, allow_nan=False)
    db = nhn_record_connection('reports.sqlite3')
    try:
        with db:
            ptw_record_schema(db)
            current = db.execute('SELECT owner,revision FROM work_permit_plans WHERE id=?', (data['id'],)).fetchone()
            if current:
                if current[0] != actor: raise PermissionError('본인이 작성한 작업계획서만 수정할 수 있습니다.')
                if revision is None or current[1] != revision:
                    raise ValueError('다른 창에서 변경된 계획서입니다. 작성내용 백업을 내려받고 저장목록에서 다시 열어 주세요.')
                result = db.execute('''UPDATE work_permit_plans SET updated=?,project=?,trade=?,work_date=?,payload=?,revision=revision+1
                    WHERE id=? AND owner=? AND revision=?''',
                    (now, data['meta']['project'], data['meta']['trade'] or '', data['meta']['date'], encoded, data['id'], actor, revision))
                if result.rowcount != 1: raise ValueError('저장 중 계획서가 변경되었습니다. 백업 후 다시 열어 주세요.')
                revision += 1
            else:
                if revision is not None: raise ValueError('저장된 계획서를 확인해 주세요.')
                db.execute('INSERT INTO work_permit_plans VALUES(?,?,?,?,?,?,?,?,1)',
                    (data['id'], actor, now, now, data['meta']['project'], data['meta']['trade'] or '', data['meta']['date'], encoded))
                revision = 1
    finally: db.close()
    return revision, now


def ptw_record_list(actor):
    actor = report_history_identity(actor)
    db = nhn_record_connection('reports.sqlite3')
    try:
        if 'work_permit_plans' not in report_history_tables(db): return []
        records = db.execute('SELECT id,project,trade,work_date,updated FROM work_permit_plans WHERE owner=? ORDER BY updated DESC LIMIT 100', (actor,)).fetchall()
        return [dict(zip(('id', 'project', 'trade', 'date', 'updated'), (row[0], canonical_site_label(row[1]), *row[2:]))) for row in records]
    finally: db.close()


def ptw_record_load(actor, record_id):
    actor = report_history_identity(actor)
    db = nhn_record_connection('reports.sqlite3')
    try:
        if 'work_permit_plans' not in report_history_tables(db): raise ValueError('저장된 계획서가 없습니다.')
        row = db.execute('SELECT payload,revision,updated FROM work_permit_plans WHERE id=? AND owner=?', (str(record_id), actor)).fetchone()
        if not row: raise PermissionError('본인이 작성한 작업계획서만 열 수 있습니다.')
        return ptw_validate(json.loads(row[0])), row[1], row[2]
    finally: db.close()


def ptw_initialize(actor):
    if st.session_state.get('ptw_actor') != str(actor):
        for key in list(st.session_state):
            if key.startswith('ptw_'): del st.session_state[key]
        st.session_state.ptw_actor = str(actor)
    st.session_state.setdefault('ptw_data', ptw_default())
    st.session_state.ptw_data['meta']['project'] = canonical_site_label(st.session_state.ptw_data['meta'].get('project', ''))
    for key in list(st.session_state):
        if str(key).startswith('ptw_w_') and str(key).endswith('_meta_project'):
            st.session_state[key] = canonical_site_label(st.session_state[key])
    st.session_state.setdefault('ptw_step', PTW_STEPS[0])
    st.session_state.setdefault('ptw_revision', None)
    st.session_state.setdefault('ptw_generation', 0)
    st.session_state.setdefault('ptw_dirty', False)


def ptw_try_save(actor, explicit=False):
    if not st.session_state.get('ptw_dirty') and st.session_state.get('ptw_revision') is not None:
        if explicit: st.session_state.ptw_notice = '현재 작성내용이 저장되어 있습니다.'
        return True
    try:
        revision, updated = ptw_record_save(actor, st.session_state.ptw_data, st.session_state.ptw_revision)
        st.session_state.ptw_revision = revision
        st.session_state.ptw_saved_at = updated
        st.session_state.ptw_dirty = False
        st.session_state.pop('ptw_save_error', None)
        if explicit: st.session_state.ptw_notice = '작업계획서를 저장했습니다.'
        return True
    except Exception as exc:
        st.session_state.ptw_save_error = '저장하지 못했습니다: '+str(exc)
        return False


def ptw_changed(actor, group, field, widget_key, work_id=None):
    data = st.session_state.ptw_data
    target = data[group] if work_id is None else next(w for w in data['works'] if w['id'] == work_id)
    value = st.session_state[widget_key]
    if isinstance(value, (datetime.date, datetime.time)): value = value.isoformat()
    if group == 'checks': target['checks'][field] = value
    else: target[field] = value
    if not (group == 'review' and field == 'confirmed'):
        data['review']['confirmed'] = False
        for key in list(st.session_state):
            if key.startswith('ptw_w_') and key.endswith('_review_confirmed'): st.session_state[key] = False
    st.session_state.ptw_dirty = True
    st.session_state.pop('ptw_report', None)
    ptw_try_save(actor)


def ptw_widget(actor, label, group, field, *, work=None, kind='text', options=None, help=None, placeholder=None, max_chars=12000):
    target = st.session_state.ptw_data[group] if work is None else work
    value = target['checks'][field] if group == 'checks' else target.get(field)
    key = 'ptw_w_'+str(st.session_state.ptw_generation)+'_'+(work['id'] if work else group)+'_'+field
    if key not in st.session_state:
        if kind == 'date': value = datetime.date.fromisoformat(value)
        elif kind == 'time': value = datetime.time.fromisoformat(value)
        st.session_state[key] = value
    kwargs = dict(key=key, on_change=ptw_changed, args=(actor, group, field, key, work['id'] if work else None), help=help)
    if kind == 'area': return st.text_area(label, height=110, max_chars=max_chars, placeholder=placeholder, **kwargs)
    if kind == 'date': return st.date_input(label, **kwargs)
    if kind == 'time': return st.time_input(label, step=900, **kwargs)
    if kind == 'number': return st.number_input(label, min_value=0, max_value=10000, step=1, **kwargs)
    if kind == 'check': return st.checkbox(label, **kwargs)
    if kind == 'select': return st.selectbox(label, options, placeholder=placeholder, **kwargs)
    if kind == 'multi': return st.multiselect(label, options, **kwargs)
    return st.text_input(label, max_chars=min(max_chars,1000), placeholder=placeholder, **kwargs)


def ptw_go(actor, index):
    # 저장 오류가 발생해도 입력을 유지하고 충돌 자료는 덮어쓰지 않음.
    ptw_try_save(actor)
    st.session_state.ptw_step = PTW_STEPS[max(0, min(3, index))]
    st.session_state.ptw_back_revision = st.session_state.get('ptw_back_revision', 0)+1


def ptw_step_changed(actor):
    ptw_try_save(actor)
    st.session_state.ptw_back_revision = st.session_state.get('ptw_back_revision', 0)+1


def ptw_add_work(actor, use_add_choice=False):
    import uuid
    data = st.session_state.ptw_data
    trade = st.session_state.get('ptw_add_trade') if use_add_choice else data['meta'].get('trade')
    if trade not in PTW_TRADES:
        st.session_state.ptw_action_error = '먼저 공종을 선택해 주세요.'; return
    if len(data['works']) >= 20:
        st.session_state.ptw_action_error = '작업은 한 계획서에 20개까지 추가할 수 있습니다.'; return
    template = PTW_TRADES[trade]
    work = dict(id=uuid.uuid4().hex, trade=trade, name=template['name'], place=data['meta']['place'],
        start_date=data['meta']['date'], end_date=data['meta']['date'], start='09:00:00', end='18:00:00',
        responsible='', safety_manager='', workers=0, hazards=list(template['hazards']), details='',
        risk=template['risk'], controls=template['controls'], measurements='',
        checks={label: '미확인' for label in template['checks']})
    data['works'].append(work); data['review']['confirmed'] = False
    st.session_state.ptw_active_work = work['id']; st.session_state.ptw_dirty = True
    st.session_state.pop('ptw_report', None)
    ptw_go(actor,1)
    st.session_state.ptw_notice = '작업을 추가했습니다. 예시 안전대책을 현장 여건에 맞게 수정해 주세요.'


def ptw_work_selected(actor):
    ptw_try_save(actor)


def ptw_remove_work(actor):
    data = st.session_state.ptw_data
    work_id = st.session_state.pop('ptw_delete_work', None)
    data['works'] = [w for w in data['works'] if w['id'] != work_id]
    data['review']['confirmed'] = False
    st.session_state.ptw_active_work = data['works'][0]['id'] if data['works'] else None
    st.session_state.ptw_dirty = True; st.session_state.pop('ptw_report', None)
    ptw_try_save(actor)


def ptw_request_remove(work_id):
    st.session_state.ptw_delete_work = work_id


def ptw_clear_delete():
    st.session_state.pop('ptw_delete_work', None)


def ptw_reset_widgets():
    for key in list(st.session_state):
        if key.startswith('ptw_w_') or key in ('ptw_active_work','ptw_report','ptw_delete_work','ptw_action_error'):
            del st.session_state[key]
    st.session_state.ptw_generation += 1


def ptw_new(actor):
    if st.session_state.ptw_dirty and not ptw_try_save(actor): return
    ptw_reset_widgets()
    st.session_state.ptw_data = ptw_default()
    st.session_state.ptw_revision = None; st.session_state.ptw_dirty = False
    st.session_state.pop('ptw_saved_at', None)
    st.session_state.ptw_step = PTW_STEPS[0]
    st.session_state.ptw_notice = '새 작업계획서를 작성합니다. 기존 저장자료는 저장목록에서 다시 열 수 있습니다.'


def ptw_open(actor, discard=False):
    record_id = st.session_state.get('ptw_saved_choice')
    if not record_id: return
    if not discard and st.session_state.ptw_dirty and not ptw_try_save(actor): return
    try:
        data, revision, updated = ptw_record_load(actor, record_id)
        ptw_reset_widgets(); st.session_state.ptw_data = data
        st.session_state.ptw_revision = revision; st.session_state.ptw_saved_at = updated
        st.session_state.ptw_dirty = False; st.session_state.ptw_step = PTW_STEPS[0]
        st.session_state.pop('ptw_save_error', None)
        st.session_state.ptw_notice = '저장된 작업계획서를 불러왔습니다.'
    except Exception as exc: st.session_state.ptw_action_error = str(exc)


def ptw_missing(data):
    missing = []
    meta = data['meta']
    for field, label in [('project','공사명'),('place','작업장소'),('author','계획서 작성자'),('reviewer','계획서 검토자')]:
        if not str(meta.get(field) or '').strip(): missing.append(label)
    if meta.get('trade') not in PTW_TRADES: missing.append('주요 공종')
    if not data['works']: missing.append('세부 작업 1개 이상')
    for i, work in enumerate(data['works'],1):
        for field, label in [('name','작업명'),('place','작업장소'),('responsible','작업책임자'),('safety_manager','안전관리자·담당자'),('details','세부 작업내용'),('risk','유해·위험요인'),('controls','작업 안전대책')]:
            if not work[field].strip(): missing.append(f'작업 {i} · {label}')
        if work['workers'] <= 0: missing.append(f'작업 {i} · 근로자 수')
        start = datetime.datetime.fromisoformat(work['start_date']+'T'+work['start'])
        end = datetime.datetime.fromisoformat(work['end_date']+'T'+work['end'])
        if end <= start: missing.append(f'작업 {i} · 종료일시가 시작일시보다 늦어야 합니다')
        checks = PTW_TRADES[work['trade']]['checks']
        if any(work['checks'].get(label,'미확인') == '미확인' for label in checks): missing.append(f'작업 {i} · 안전조치 확인')
        if work['trade'] == '밀폐공간' and not work['measurements'].strip(): missing.append(f'작업 {i} · 공기상태 측정기록')
    if data['review']['instructions'].strip() and not data['review']['treatment'].strip(): missing.append('지적사항 처리결과')
    if not data['review']['confirmed']: missing.append('작성내용 현장 대조 확인')
    return missing


def ptw_report_rows(data):
    meta = data['meta']; review = data['review']
    basics = [('공사명',meta['project']),('공사장 주소',meta['address']),('주요 공종',meta['trade'] or ''),
              ('세부공종',meta['subtrade']),('작업일자',meta['date']),('작업장소',meta['place']),
              ('시공사',meta['company']),('담당부서',meta['department']),('계획서 작성자',meta['author']),
              ('계획서 검토자',meta['reviewer']),('승인자',meta['approver']),('비상연락',meta['contact'])]
    sections = []
    for i, w in enumerate(data['works'],1):
        sections.append((f'{i}. {w["name"] or "작업명 미입력"}', [
            ('공종',w['trade']),('작업장소',w['place']),('작업시간',w['start_date']+' '+w['start'][:5]+' ~ '+w['end_date']+' '+w['end'][:5]),
            ('작업책임자',w['responsible']),('안전관리자·담당자',w['safety_manager']),('근로자 수',str(w['workers'])+'명'),
            ('유해·위험작업',', '.join(w['hazards'])),('세부 작업내용',w['details']),('유해·위험요인',w['risk']),
            ('작업 안전대책',w['controls']),('현장 측정·점검기록',w['measurements']),
            ('안전조치 확인','\n'.join(label+' : '+w['checks'].get(label,'미확인') for label in PTW_TRADES[w['trade']]['checks']))]))
    return basics, sections, [('지적사항',review['instructions']),('처리결과',review['treatment']),('계획 변경사항',review['changes'])]


def ptw_hwpx(data, submission=False):
    """첨부 15개 작성 항목과 실제 승인용 서명란. 전체 입력을 생략 없이 보존."""
    data = ptw_validate(data)
    if submission and ptw_missing(data): raise ValueError('검토 제출본의 미입력·미확인 항목을 먼저 확인해 주세요.')
    doc = HwpxDocument.new()
    ns = {'hp':'http://www.hancom.co.kr/hwpml/2011/paragraph'}
    page = doc.sections[0].element.find('.//hp:pagePr',ns)
    if page is not None:
        page.set('width','59528'); page.set('height','84189')
        margin = page.find('hp:margin',ns)
        if margin is not None:
            for side in ('left','right','top','bottom'): margin.set(side,'4252')
    width = 51024
    styles = {}
    for alignment in ('LEFT','CENTER','RIGHT'):
        p = doc.add_paragraph('')
        doc.set_paragraph_format(paragraph_index=len(doc.paragraphs)-1,alignment=alignment,line_spacing_percent=135,spacing_after_pt=3)
        styles[alignment] = p.element.get('paraPrIDRef'); p.remove()
    def paragraph(text, size=10, bold=False, align='LEFT', new_page=False):
        for i,line in enumerate(str(text).splitlines() or ['']):
            p = doc.add_paragraph('',para_pr_id_ref=styles[align],pageBreak='1' if new_page and i==0 else '0')
            p.add_run(line,font='맑은 고딕',size=size,bold=bold)
    def cell_text(cell,text,bold=False,align='LEFT',size=10):
        cell.set_text('')
        for i,line in enumerate(str(text).splitlines() or ['']):
            p = cell.paragraphs[0] if i==0 else cell.add_paragraph('')
            p.element.set('paraPrIDRef',styles[align]); p.add_run(line,font='맑은 고딕',size=size,bold=bold)
    def pairs(values):
        # 각 항목은 독립 표. 내용이 길면 여러 행으로 분할하여 페이지 밖으로 잘리지 않음.
        import textwrap
        for label,value in values:
            raw = str(value or '미입력')
            lines = []
            for line in raw.splitlines() or ['']:
                lines.extend(textwrap.wrap(line,width=38,replace_whitespace=False,drop_whitespace=False) or [''])
            for offset in range(0,len(lines),8):
                chunk = '\n'.join(lines[offset:offset+8])
                height = max(2400, len(lines[offset:offset+8])*1500+800)
                table = doc.add_table(rows=1,cols=2,width=width,height=height)
                table.element.set('pageBreak','CELL')
                for j,cw in enumerate((11000,width-11000)): table.cell(0,j).set_size(width=cw,height=height)
                cell_text(table.cell(0,0),label+(' (계속)' if offset else ''),bold=True,size=9)
                cell_text(table.cell(0,1),chunk,size=10)
    title = '사전작업허가제 작업계획서'
    paragraph(title,size=19,bold=True,align='CENTER')
    mode = '검토 제출본 · 실제 승인·서명 전' if submission else '초안 · 미입력·미확인 항목 포함'
    paragraph(mode,size=10,align='CENTER')
    paragraph('')
    meta = data['meta']; basics,sections,review = ptw_report_rows(data)
    paragraph('1. 작업 개요',size=12,bold=True)
    # 원본 양식처럼 공사명·날짜, 공종·장소, 작성자·검토자를 같은 행에 배치.
    grid = [
        ['공사명',meta['project'],'작업일자',meta['date']],
        ['공사장 주소',meta['address'],'작업장소',meta['place']],
        ['공종',meta['trade'] or '미입력','세부공종',meta['subtrade']],
        ['시공사',meta['company'],'담당부서',meta['department']],
        ['계획서 작성자',meta['author'],'계획서 검토자',meta['reviewer']],
        ['승인자',meta['approver'],'비상연락',meta['contact']],
    ]
    # 개요에는 짧은 요약, 긴 입력은 뒤의 기본정보 상세에 전체 수록.
    summary = doc.add_table(rows=len(grid),cols=4,width=width,height=3200*len(grid))
    widths = (7000,18512,7000,18512)
    for i,row in enumerate(grid):
        for j,value in enumerate(row):
            summary.cell(i,j).set_size(width=widths[j],height=3200)
            text = str(value or '미입력')
            if j%2 and len(text)>30: text=text[:30]+'… (상세 참조)'
            cell_text(summary.cell(i,j),text,bold=j%2==0,size=9)
    paragraph('')
    paragraph('2. 세부 작업 목록',size=12,bold=True)
    if not data['works']: paragraph('등록된 세부 작업 없음')
    else:
        for i,w in enumerate(data['works'],1):
            paragraph(f'{i}. {w["name"] or "작업명 미입력"} / {w["trade"]}',bold=True)
            paragraph(w['start_date']+' '+w['start'][:5]+' ~ '+w['end_date']+' '+w['end'][:5]+' / 근로자 '+str(w['workers'])+'명',size=9)
    paragraph('')
    paragraph('3. 작성·검토·승인',size=12,bold=True)
    sign = doc.add_table(rows=2,cols=3,width=width,height=9000)
    for j,(role,name) in enumerate([('작성자',meta['author']),('검토자',meta['reviewer']),('승인자',meta['approver'])]):
        sign.cell(0,j).set_size(width=width//3,height=2200)
        sign.cell(1,j).set_size(width=width//3,height=6800)
        cell_text(sign.cell(0,j),role,bold=True,align='CENTER')
        cell_text(sign.cell(1,j),(name or '성명: __________________')+'\n서명·날인: ______________\n확인일시: ______________',size=9)
    paragraph('작업 착수는 현장 안전조치 확인 및 실제 승인 후 진행합니다. 성명 입력·파일 생성은 승인 또는 서명을 의미하지 않습니다.',size=9)
    paragraph('생성일시: '+datetime.datetime.now(ZoneInfo('Asia/Seoul')).strftime('%Y-%m-%d %H:%M'),size=9,align='RIGHT')
    extended = [(label,value) for label,value in basics if len(str(value))>30]
    if extended:
        paragraph('기본정보 상세',size=14,bold=True,new_page=True)
        pairs(extended)
    for title,values in sections:
        paragraph('세부 작업계획 · '+title,size=14,bold=True,new_page=True)
        pairs(values)
    paragraph('')
    paragraph('검토·보완 및 계획 변경',size=14,bold=True,new_page=not sections)
    pairs(review)
    paragraph('작성내용 현장 대조 확인: '+('확인' if data['review']['confirmed'] else '미확인'),size=10)
    if not submission:
        missing = ptw_missing(data)
        if missing:
            paragraph('보완이 필요한 항목',size=12,bold=True)
            for label in missing: paragraph('· '+label,size=9)
    output = io.BytesIO(); doc.save_to_stream(output)
    return output.getvalue()


def ptw_build_report(actor, submission=False):
    if not _perf_actor_allowed(actor): return
    data = st.session_state.ptw_data
    try:
        with keco_loading('작업계획서를 만들고 있습니다', kind='steps', steps=('작성내용 확인', '한글 작성', '저장·파일 준비')) as loading:
            loading.stage(1)
            raw = ptw_hwpx(data,submission)
            loading.stage(2)
            name = re.sub(r'[\\/:*?"<>|\r\n]','_',data['meta']['project'] or '현장')[:60]
            filename = f'작업계획서_{name}_{data["meta"]["date"]}_{"검토제출본" if submission else "초안"}.hwpx'
            st.session_state.ptw_report = dict(data=raw,name=filename,fingerprint=ptw_fingerprint(data))
            ptw_try_save(actor)
            st.session_state.ptw_notice = '한글 보고서를 만들었습니다. 아래 다운로드 버튼을 눌러 주세요.'
    except Exception as exc:
        st.session_state.pop('ptw_report',None)
        st.session_state.ptw_action_error = '보고서 생성 실패: '+str(exc)


def ptw_render_basics(actor):
    st.subheader('기본정보와 주요 공종을 선택하세요')
    st.caption('공사장명 또는 주소, 작업 위치, 계획서 작성자와 검토자를 입력합니다.')
    with st.container(border=True):
        a,b = st.columns([2,1])
        with a: ptw_widget(actor,'공사명 *','meta','project',placeholder='예: ○○ 환경시설 설치사업',max_chars=300)
        with b: ptw_widget(actor,'작업일자','meta','date',kind='date')
        ptw_widget(actor,'공사장 주소','meta','address',placeholder='공사현장 주소',max_chars=500)
        a,b = st.columns(2)
        with a: ptw_widget(actor,'주요 공종 *','meta','trade',kind='select',options=list(PTW_TRADES),placeholder='공종을 선택하세요')
        with b: ptw_widget(actor,'세부공종','meta','subtrade',placeholder='예: 하수관로 터파기',max_chars=300)
        ptw_widget(actor,'작업장소 *','meta','place',placeholder='예: 관로 구간 STA. 0+120 / 지하 1층 기계실',max_chars=500)
        a,b = st.columns(2)
        with a: ptw_widget(actor,'시공사','meta','company',max_chars=200)
        with b: ptw_widget(actor,'담당부서','meta','department',max_chars=200)
        a,b = st.columns(2)
        with a: ptw_widget(actor,'계획서 작성자 *','meta','author',placeholder='소속·성명',help='공사 시공사 또는 현장관리인',max_chars=200)
        with b: ptw_widget(actor,'계획서 검토자 *','meta','reviewer',placeholder='소속·성명',help='공사 감리자 등 현장 검토 담당자',max_chars=200)
        a,b = st.columns(2)
        with a: ptw_widget(actor,'승인자','meta','approver',placeholder='현장 절차에 따른 허가권자',max_chars=200)
        with b: ptw_widget(actor,'비상연락','meta','contact',placeholder='담당자·연락처',max_chars=300)
    trade = st.session_state.ptw_data['meta'].get('trade')
    if trade in PTW_TRADES:
        template = PTW_TRADES[trade]
        st.caption('선택한 공종의 작성 예시: '+(template['risk'] or '위험요인과 안전대책을 직접 입력합니다.'))
    st.button('선택 공종으로 작업 추가 →',type='primary',key='ptw_add_initial',on_click=ptw_add_work,args=(actor,),width='stretch')


def ptw_render_work(actor):
    data = st.session_state.ptw_data
    st.subheader('작업내용과 안전대책을 작성하세요')
    st.caption('예시 위험요인·안전대책은 수정할 수 있습니다. 작업시간은 실제 예정일시로 바꿔 주세요.')
    with st.expander('다른 공종의 작업 추가',expanded=not data['works']):
        st.selectbox('추가할 공종',list(PTW_TRADES),key='ptw_add_trade',index=None,placeholder='공종을 선택하세요')
        st.button('작업 추가',key='ptw_add_another',on_click=ptw_add_work,args=(actor,True))
    if not data['works']:
        st.info('공종을 선택한 뒤 ‘작업 추가’를 눌러 주세요.'); return
    ids = [w['id'] for w in data['works']]
    if st.session_state.get('ptw_active_work') not in ids: st.session_state.ptw_active_work = ids[0]
    names = {w['id']:f'{i}. {w["name"] or "작업명 미입력"} · {w["trade"]}' for i,w in enumerate(data['works'],1)}
    st.selectbox('작성할 작업 선택',ids,format_func=lambda value:names[value],key='ptw_active_work',on_change=ptw_work_selected,args=(actor,))
    work = next(w for w in data['works'] if w['id']==st.session_state.ptw_active_work)
    with st.container(border=True):
        ptw_widget(actor,'작업명 *','works','name',work=work,max_chars=300)
        ptw_widget(actor,'작업장소 *','works','place',work=work,max_chars=500)
        start,end = st.columns(2)
        with start:
            ptw_widget(actor,'작업 시작일','works','start_date',work=work,kind='date')
            ptw_widget(actor,'시작시간','works','start',work=work,kind='time')
        with end:
            ptw_widget(actor,'작업 종료일','works','end_date',work=work,kind='date')
            ptw_widget(actor,'종료시간','works','end',work=work,kind='time')
        a,b,c = st.columns([2,2,1])
        with a: ptw_widget(actor,'작업책임자 *','works','responsible',work=work,placeholder='소속·성명',max_chars=200)
        with b: ptw_widget(actor,'안전관리자·담당자 *','works','safety_manager',work=work,placeholder='소속·성명',max_chars=200)
        with c: ptw_widget(actor,'근로자 수 *','works','workers',work=work,kind='number')
        ptw_widget(actor,'유해·위험작업','works','hazards',work=work,kind='multi',options=PTW_HAZARDS)
        ptw_widget(actor,'세부 작업내용 *','works','details',work=work,kind='area',placeholder=PTW_TRADES[work['trade']]['detail_help'])
        ptw_widget(actor,'유해·위험요인 *','works','risk',work=work,kind='area')
        ptw_widget(actor,'작업 안전대책 *','works','controls',work=work,kind='area')
        ptw_widget(actor,'현장 측정·점검기록'+(' *' if work['trade']=='밀폐공간' else ''),'works','measurements',work=work,kind='area',
                   placeholder='필요한 실제 측정결과를 입력하세요. 예: 측정시간·위치·측정자·산소/가스 농도 또는 검전·장비점검 결과')
    st.button('현재 작업 삭제',key='ptw_remove_request',on_click=ptw_request_remove,args=(work['id'],))
    if st.session_state.get('ptw_delete_work'):
        st.warning('현재 선택한 작업내용을 삭제하시겠습니까?')
        a,b = st.columns(2)
        with a: st.button('작업 삭제 확인',key='ptw_remove_confirm',on_click=ptw_remove_work,args=(actor,))
        with b: st.button('취소',key='ptw_remove_cancel',on_click=ptw_clear_delete)


def ptw_render_review(actor):
    data = st.session_state.ptw_data
    st.subheader('안전조치와 검토·보완사항을 확인하세요')
    st.caption('실제 현장 확인 결과를 선택합니다. 작성 예시를 불러와도 확인 상태는 자동 완료되지 않습니다.')
    if not data['works']: st.info('먼저 세부 작업을 추가해 주세요.')
    for i,work in enumerate(data['works'],1):
        with st.expander(f'{i}. {work["name"] or "작업명 미입력"} · 안전조치 확인',expanded=True):
            for label in PTW_TRADES[work['trade']]['checks']:
                ptw_widget(actor,label,'checks',label,work=work,kind='select',options=PTW_CHECK_STATES)
    with st.container(border=True):
        ptw_widget(actor,'지적사항','review','instructions',kind='area',placeholder='검토자가 보완을 요청한 사항. 없으면 비워 두세요.')
        ptw_widget(actor,'처리결과','review','treatment',kind='area',placeholder='각 지적사항에 대한 조치내용·담당자·완료일시')
        ptw_widget(actor,'계획 변경사항','review','changes',kind='area',placeholder='작성자·검토자 협의에 따른 변경내용 및 협의일시')
        ptw_widget(actor,'작성내용을 현장 여건과 대조하여 확인했습니다.','review','confirmed',kind='check')
    st.caption('작업계획서 작성 후 현장 절차에 따라 검토·승인 및 서명·날인을 받습니다.')


def ptw_render_report(actor):
    from html import escape
    data = st.session_state.ptw_data; meta = data['meta']
    st.subheader('내용을 확인하고 한글파일로 내려받으세요')
    st.markdown('<div class="ptw-summary"><span><strong>'+str(len(data['works']))+'</strong>개 작업</span><span>'+escape(meta['project'] or '공사명 미입력')+'</span><span>'+escape(meta['date'])+'</span></div>',unsafe_allow_html=True)
    basics,sections,review = ptw_report_rows(data)
    with st.expander('보고서 내용 미리보기',expanded=True):
        st.dataframe(pd.DataFrame(basics,columns=['항목','작성내용']),hide_index=True,width='stretch')
        for title,rows in sections:
            st.markdown('**'+title+'**')
            st.dataframe(pd.DataFrame(rows,columns=['항목','작성내용']),hide_index=True,width='stretch')
        st.dataframe(pd.DataFrame(review,columns=['항목','작성내용']),hide_index=True,width='stretch')
    missing = ptw_missing(data)
    if missing:
        st.info(f'미입력·미확인 {len(missing)}개 항목이 있습니다. 초안은 지금 내려받을 수 있습니다.')
        with st.expander('보완할 항목 보기'):
            for label in missing: st.write('· '+label)
    else: st.success('작성내용과 안전조치 확인을 마쳤습니다. 검토 제출본을 만들 수 있습니다.')
    a,b = st.columns(2)
    with a: st.button('초안 한글파일 만들기',key='ptw_generate_draft',on_click=ptw_build_report,args=(actor,False),width='stretch')
    with b: st.button('검토 제출본 만들기',type='primary',key='ptw_generate_submission',on_click=ptw_build_report,args=(actor,True),disabled=bool(missing),width='stretch')
    report = st.session_state.get('ptw_report')
    if report and report['fingerprint']==ptw_fingerprint(data):
        st.download_button('한글 보고서 다운로드 (.hwpx)',data=report['data'],file_name=report['name'],mime='application/hwp+zip',key='ptw_download_hwpx',width='stretch')
        st.caption('한글에서 열어 수정·인쇄할 수 있습니다. 작성·검토·승인 서명란이 포함됩니다.')


